def plain_wiki_text(value: str) -> str:
    text = html.unescape(str(value or ""))
    text = re.sub(r"<!--.*?-->", "", text, flags=re.S)
    text = re.sub(r"\[\[([^]|]+)\|([^]]+)\]\]", r"\2", text)
    text = re.sub(r"\[\[([^]]+)\]\]", r"\1", text)
    text = re.sub(r"\{\{[^{}]*\}\}", "", text)
    text = re.sub(r"<[^>]+>", "", text)
    return re.sub(r"\s+", " ", text).strip()

def validate_fandom_origin(origin: str) -> str:
    parsed = urlparse(origin)
    host = (parsed.hostname or "").lower()
    if parsed.scheme != "https" or not host.endswith(".fandom.com"):
        raise ValueError("FandomのHTTPS URLを指定してください。")
    return f"https://{host}"

def page_parts(page_url: str) -> tuple[str, str]:
    parsed = urlparse(str(page_url).strip())
    origin = validate_fandom_origin(f"{parsed.scheme}://{parsed.netloc}")
    marker = "/wiki/"
    if marker not in parsed.path:
        raise ValueError("FandomのページURL（/wiki/を含むURL）を指定してください。")
    title = unquote(parsed.path.split(marker, 1)[1]).replace("_", " ")
    if not title:
        raise ValueError("ページ名を取得できませんでした。")
    return origin, title

def api_get(origin: str, params: dict[str, Any]) -> dict[str, Any]:
    response = SESSION.get(f"{validate_fandom_origin(origin)}/api.php", params=params, timeout=45)
    response.raise_for_status()
    payload = response.json()
    if "error" in payload:
        raise RuntimeError(payload["error"].get("info", "Fandom APIでエラーが発生しました。"))
    return payload

def api_get_language(origin: str, language: str, params: dict[str, Any]) -> dict[str, Any]:
    """Call a language-specific Fandom wiki API such as /ja/api.php."""
    lang = re.sub(r"[^a-z-]", "", str(language or "").casefold())
    if not lang:
        return api_get(origin, params)
    response = SESSION.get(
        f"{validate_fandom_origin(origin)}/{lang}/api.php",
        params=params,
        timeout=45,
    )
    response.raise_for_status()
    payload = response.json()
    if "error" in payload:
        raise RuntimeError(payload["error"].get("info", "Fandom APIでエラーが発生しました。"))
    return payload

def audio_duration_from_imageinfo(info: dict[str, Any]) -> float:
    """Read audio duration from MediaWiki imageinfo metadata without downloading."""
    for item in info.get("metadata", []) or []:
        name = str(item.get("name", "")).casefold()
        if name in {"playtime_seconds", "duration", "length"}:
            try:
                value = float(item.get("value", 0) or 0)
                if value > 0:
                    return value
            except (TypeError, ValueError):
                pass
    return 0.0

def rendered_dialogue_for_files(rendered_html: str, filenames: set[str]) -> dict[str, str]:
    """Extract the spoken text following Media:<filename> from rendered quest HTML."""
    if not rendered_html or not filenames:
        return {}

    value = html.unescape(str(rendered_html))
    # Keep useful visual line boundaries before removing tags.
    value = re.sub(
        r"(?i)<\s*(?:br|/p|/li|/dd|/dt|/tr|/div|/table|/section|/h[1-6])\b[^>]*>",
        "\n",
        value,
    )
    value = re.sub(r"<[^>]+>", " ", value)
    value = value.replace("\xa0", " ")
    value = re.sub(r"[ \t\r\f\v]+", " ", value)
    value = re.sub(r"\n+", "\n", value)

    wanted = {normalized_file_title(name): name for name in filenames}
    found: dict[str, str] = {}

    # The rendered quest pages expose lines in the form:
    # Media:vo ... paimon 01.ogg パイモン: 台詞
    for line in value.splitlines():
        line = line.strip()
        if not line:
            continue
        lower = normalized_file_title(line)
        for key, original in wanted.items():
            short_key = normalized_file_title(Path(original).name)
            if short_key not in lower:
                continue
            pos = lower.find(short_key)
            tail = line[pos + len(Path(original).name):].strip(" ：:")
            if not tail:
                continue
            # Drop the speaker name and keep only the actual spoken text.
            match = re.match(r"[^：:]{1,80}[：:]\s*(.+)$", tail)
            spoken = (match.group(1) if match else tail).strip()
            spoken = re.sub(r"\s+", " ", spoken)
            if spoken and len(spoken) >= 2:
                found[key] = spoken
            break

    return found

def rendered_media_urls_for_files(rendered_html: str, filenames: set[str]) -> dict[str, str]:
    """Extract the actual audio URL embedded in a Japanese Fandom page."""
    if not rendered_html or not filenames:
        return {}

    wanted = {
        normalized_file_title(Path(str(name)).name): Path(str(name)).name
        for name in filenames
    }
    found: dict[str, str] = {}
    raw = html.unescape(str(rendered_html))

    for match in re.finditer(r'href\s*=\s*["\']([^"\']+)["\']', raw, flags=re.I):
        href = html.unescape(match.group(1)).strip()
        if href.startswith("//"):
            href = "https:" + href
        parsed = urlparse(href)
        host = (parsed.hostname or "").casefold()
        if not host.endswith("wikia.nocookie.net"):
            continue

        path = unquote(parsed.path)
        media_match = re.search(
            r"/([^/]+\.(?:ogg|oga|wav|mp3|flac))(?:/|$)",
            path,
            flags=re.I,
        )
        if not media_match:
            continue
        media_name = media_match.group(1).replace("_", " ")
        key = normalized_file_title(media_name)
        if key in wanted and key not in found:
            found[key] = href

    return found

def query_pages(origin: str, titles: list[str], prop: str = "info") -> list[dict[str, Any]]:
    pages: list[dict[str, Any]] = []
    for start in range(0, len(titles), 40):
        data = api_get(origin, {
            "action": "query", "titles": "|".join(titles[start:start + 40]),
            "prop": prop, "cllimit": "max", "iiprop": "url|size|mime|sha1",
            "format": "json", "formatversion": 2,
        })
        pages.extend(data.get("query", {}).get("pages", []))
    return pages

def is_character_page(page: dict[str, Any]) -> bool:
    categories = {item.get("title", "") for item in page.get("categories", [])}
    return "Category:Characters" in categories or "Category:NPCs" in categories

def resolve_character_title(origin: str, character: str) -> str:
    name = str(character or "").strip()
    if not name:
        return ""
    exact = query_pages(origin, [name], "info|categories")
    if exact and "missing" not in exact[0] and is_character_page(exact[0]):
        return str(exact[0].get("title", ""))
    search = api_get(origin, {
        "action": "query", "list": "search", "srsearch": f'"{name}"',
        "srnamespace": 0, "srlimit": 100, "format": "json", "formatversion": 2,
    })
    titles = [str(item.get("title", "")) for item in search.get("query", {}).get("search", [])]
    candidates: list[str] = []
    for page in query_pages(origin, titles, "info|categories"):
        title = str(page.get("title", ""))
        categories = {item.get("title", "") for item in page.get("categories", [])}
        if is_character_page(page) and f"Category:{title}" in categories:
            candidates.append(title)
    unique = list(dict.fromkeys(candidates))
    return unique[0] if len(unique) == 1 else ""

def category_members(origin: str, category_title: str, limit: int = 1000) -> list[str]:
    titles: list[str] = []
    continuation: dict[str, Any] = {}
    while len(titles) < limit:
        params: dict[str, Any] = {
            "action": "query", "list": "categorymembers", "cmtitle": category_title,
            "cmnamespace": 6, "cmlimit": "max", "format": "json", "formatversion": 2,
            **continuation,
        }
        data = api_get(origin, params)
        titles.extend(str(item.get("title", "")) for item in data.get("query", {}).get("categorymembers", []))
        if "continue" not in data:
            break
        continuation = {k: v for k, v in data["continue"].items() if k != "continue"}
    return titles[:limit]

def normalized_words(value: str) -> str:
    return re.sub(r"[^0-9a-z]+", " ", unquote(str(value)).casefold()).strip()

def is_japanese_character_audio(page: dict[str, Any], character_title: str) -> bool:
    title = str(page.get("title", ""))
    words = normalized_words(title.removeprefix("File:"))
    character_words = normalized_words(character_title)
    if not words or not character_words or not re.search(r"\.(ogg|oga|wav|mp3|flac)$", title, flags=re.I):
        return False
    categories = {item.get("title", "") for item in page.get("categories", [])}
    japanese = (
        "Category:Japanese Voice-Overs" in categories
        or "Category:Japanese Voicelines by Character" in categories
        or any(str(category).endswith(" Japanese Voicelines") for category in categories)
        or words.startswith("vo ja ")
        or words.startswith(f"{character_words} ja ")
    )
    if not japanese:
        return False
    standard_prefix = f"vo ja {character_words}"
    if words.startswith(standard_prefix) or words.startswith(f"{character_words} ja "):
        return True
    if re.search(rf"\babout {re.escape(character_words)}\b", words):
        return False
    return bool(re.search(rf"\b{re.escape(character_words)}\b(?: \d+[a-z]?)* (ogg|oga|wav|mp3|flac)$", words))

def japanese_langlink_map(origin: str, english_titles: list[str]) -> dict[str, str]:
    """Map English page titles to their Japanese interlanguage page titles."""
    result: dict[str, str] = {}
    clean = list(dict.fromkeys(str(x).strip() for x in english_titles if str(x).strip()))
    for start in range(0, len(clean), 40):
        batch = clean[start:start + 40]
        data = api_get(origin, {
            "action": "query",
            "titles": "|".join(batch),
            "prop": "langlinks",
            "lllang": "ja",
            "lllimit": "max",
            "redirects": 1,
            "format": "json",
            "formatversion": 2,
        })
        for page in data.get("query", {}).get("pages", []):
            english_title = str(page.get("title", "")).strip()
            if not english_title:
                continue
            for link in page.get("langlinks", []) or []:
                if str(link.get("lang", "")).casefold() != "ja":
                    continue
                japanese_title = str(link.get("title") or link.get("*") or "").strip()
                if japanese_title:
                    result[english_title] = japanese_title
                    break

    # Fandom occasionally exposes interlanguage links through action=parse even
    # when query/langlinks does not return them. Check only a few missing pages.
    missing = [title for title in clean if title not in result][:12]
    for english_title in missing:
        try:
            parsed = api_get(origin, {
                "action": "parse",
                "page": english_title,
                "prop": "langlinks",
                "format": "json",
                "formatversion": 2,
            }).get("parse", {})
            for link in parsed.get("langlinks", []) or []:
                if str(link.get("lang", "")).casefold() != "ja":
                    continue
                japanese_title = str(
                    link.get("title") or link.get("*") or link.get("url") or ""
                ).strip()
                if japanese_title.startswith("http"):
                    path = unquote(urlparse(japanese_title).path)
                    marker = "/wiki/"
                    japanese_title = (
                        unquote(path.split(marker, 1)[1]).replace("_", " ")
                        if marker in path else ""
                    )
                if japanese_title:
                    result[english_title] = japanese_title
                    break
        except Exception:
            continue
    return result

def estimate_spoken_seconds(transcript: str) -> float:
    """Cheap estimate used only to avoid downloading hundreds of candidates."""
    text = re.sub(r"\s+", "", str(transcript or ""))
    if not text:
        return 5.0
    # Japanese conversational speech varies widely. This is deliberately only a
    # rough pre-download estimate; real duration is measured after download.
    return max(2.0, min(12.0, len(text) / 5.0))

def hf_audio_src(value: Any) -> str:
    """Return a playable URL from a Hugging Face dataset-viewer Audio cell."""
    if isinstance(value, dict):
        return str(value.get("src", "") or "")
    if isinstance(value, list):
        for item in value:
            if isinstance(item, dict) and item.get("src"):
                return str(item["src"])
    return ""

def hf_genshin_japanese_entries(character_title: str) -> list[dict[str, Any]]:
    """Get a bounded pool of real Japanese Genshin audio.

    The dataset's Search/Filter API is unavailable for this dataset.
    Use the ordinary paged rows endpoint and filter language/speaker locally.
    """
    global _last_fallback_status, _last_hf_scan_info

    speaker = str(character_title or "").strip()
    if not speaker:
        return []

    is_paimon = speaker.casefold() == "paimon"
    candidate_limit = 100 if is_paimon else 50
    download_limit = 100 if is_paimon else 32

    candidates: list[dict[str, Any]] = []
    seen_src: set[str] = set()
    offset = 0
    requests_done = 0
    rows_seen = 0
    max_rows = 2500
    _last_hf_scan_info = {}

    while offset < max_rows and len(candidates) < candidate_limit:
        response = None
        max_attempts = 4
        for attempt in range(max_attempts):
            response = SESSION.get(
                f"{HF_DATASET_API}/rows",
                params={
                    "dataset": HF_GENSHIN_DATASET,
                    "config": "default",
                    "split": "train",
                    "offset": offset,
                    "length": 100,
                },
                timeout=60,
            )
            if response.status_code not in {500, 502, 503, 504}:
                break
            if attempt + 1 >= max_attempts:
                raise RuntimeError(
                    f"Hugging Face rows APIの一時エラーが続いたため停止しました。"
                    f" offset={offset} HTTP {response.status_code} "
                    f"（{max_attempts}回試行）"
                )
            time.sleep(1.5 * (2 ** attempt))

        if response is None:
            raise RuntimeError(f"Hugging Face rows APIの取得に失敗しました。offset={offset}")
        response.raise_for_status()
        payload = response.json()
        rows = payload.get("rows", []) or []
        requests_done += 1
        rows_seen += len(rows)

        if not rows:
            break

        for wrapped in rows:
            row = wrapped.get("row", {}) if isinstance(wrapped, dict) else {}
            if not isinstance(row, dict):
                continue

            if str(row.get("language", "")).strip() != "Japanese":
                continue
            if str(row.get("speaker", "")).strip().casefold() != speaker.casefold():
                continue

            transcript = re.sub(r"\s+", " ", str(row.get("transcription", "") or "")).strip()
            if not transcript or transcript in {"...", "…"}:
                continue

            char_count = len(re.sub(r"\s+", "", transcript))
            if char_count < 5 or char_count > 75:
                continue

            audio_url = hf_audio_src(row.get("audio"))
            if not audio_url or audio_url in seen_src:
                continue
            seen_src.add(audio_url)

            row_idx_raw = wrapped.get("row_idx", len(candidates))
            try:
                row_idx = int(row_idx_raw)
            except (TypeError, ValueError):
                row_idx = len(candidates)

            item_type = str(row.get("type", "") or "").strip()
            game_file = str(row.get("inGameFilename", "") or "").strip()
            stem = (
                Path(game_file.replace("\\", "/")).stem
                if game_file
                else f"{speaker}_{len(candidates)+1:03d}"
            )
            filename = safe_name(
                f"HF_JA_{stem}.wav",
                f"HF_JA_{len(candidates)+1:03d}.wav",
                180,
            )

            candidates.append({
                "id": f"hf_{row_idx:06d}",
                "row_idx": row_idx,
                "file_title": f"HF:{game_file or stem}",
                "filename": filename,
                "original_filename": game_file,
                "label": item_type or "Dialog",
                "subtitle": "",
                "transcript": transcript,
                "url": audio_url,
                "size": 0,
                "mime": "audio/wav",
                "sha1": "",
                "estimated_seconds": estimate_spoken_seconds(transcript),
                "source_language": "ja",
                "source_provider": "huggingface:simon3000/genshin-voice",
            })

            if len(candidates) >= candidate_limit:
                break

        if len(rows) < 100:
            break
        offset += 100

    candidates.sort(
        key=lambda item: (
            0 if str(item.get("label", "")).casefold() == "dialog" else 1,
            abs(float(item.get("estimated_seconds", 5.0) or 5.0) - 6.0),
        )
    )

    if is_paimon:
        selected = candidates[:download_limit]
    else:
        selected = []
        estimated_total = 0.0
        for item in candidates:
            selected.append(item)
            estimated_total += float(item.get("estimated_seconds", 5.0) or 5.0)
            if len(selected) >= 22 and estimated_total >= 175.0:
                break
            if len(selected) >= download_limit:
                break

    _last_hf_scan_info = {
        "speaker": speaker,
        "candidate_limit": candidate_limit,
        "download_limit": download_limit,
        "max_rows": max_rows,
        "scanned_rows": rows_seen,
        "candidate_count": len(candidates),
        "selected_count": len(selected),
        "requests_done": requests_done,
    }
    _last_fallback_status = (
        f"Hugging Face行走査 {rows_seen}行／"
        f"日本語・キャラクター完全一致 {len(candidates)}件／"
        f"取得対象 {len(selected)}件／"
        f"API照会 {requests_done}回"
    )
    return selected

def fallback_voice_entries(origin: str, character_title: str) -> list[dict[str, Any]]:
    """Fallback source for characters without a normal Fandom Japanese VO page.

    For Genshin Impact, do NOT use localized Fandom quest-page Media links:
    those pages can show Japanese transcript while still pointing to the shared
    English audio asset. Use the Japanese rows of the genshin-voice dataset
    instead, where language, speaker, transcript and audio are explicit fields.
    """
    global _last_fallback_status, _last_hf_scan_info
    _last_fallback_status = ""
    _last_hf_scan_info = {}

    host = (urlparse(validate_fandom_origin(origin)).hostname or "").casefold()
    if host == "genshin-impact.fandom.com":
        entries = hf_genshin_japanese_entries(character_title)
        if entries:
            return entries
        _last_fallback_status = (
            _last_fallback_status
            or f"Hugging Faceで日本語の{character_title}音声を取得できませんでした。"
        )
        return []

    # Other games keep the existing conservative Fandom fallback.
    candidate_groups: list[list[str]] = []
    for category in (
        f"Category:{character_title} Japanese Voicelines",
        f"Category:{character_title} Voice-Overs",
        f"Category:{character_title} Audio",
    ):
        category_page = query_pages(origin, [category], "info")
        if category_page and "missing" not in category_page[0]:
            candidate_groups.append(category_members(origin, category))

    for candidate_titles in candidate_groups:
        unique_titles = list(dict.fromkeys(
            title for title in candidate_titles if title.startswith("File:")
        ))
        entries: list[dict[str, Any]] = []
        for page in query_pages(origin, unique_titles, "info|categories|imageinfo"):
            imageinfo = page.get("imageinfo") or []
            if not imageinfo or not is_japanese_character_audio(page, character_title):
                continue
            title = str(page.get("title", ""))
            filename = title.split(":", 1)[1]
            info = imageinfo[0]
            entries.append({
                "id": f"fallback_{len(entries):04d}",
                "file_title": title,
                "filename": filename,
                "label": Path(filename).stem,
                "subtitle": "",
                "transcript": "",
                "url": info.get("url", ""),
                "size": int(info.get("size", 0) or 0),
                "mime": info.get("mime", ""),
                "sha1": info.get("sha1", ""),
            })
        if entries:
            _last_fallback_status = f"Fandom日本語音声候補 {len(entries)}件"
            return sorted(entries, key=lambda item: normalized_words(item["filename"]))

    return []

def detect_page(game: str, character: str, custom_wiki: str) -> tuple[str, str]:
    name = str(character or "").strip()
    if not name:
        return "", "キャラクター名を入力してください。"
    if game == "その他":
        origin = validate_fandom_origin(str(custom_wiki or "").rstrip("/"))
    else:
        origin = all_game_wikis().get(game, "")
        if not origin:
            return "", "対応するFandom Wikiが設定されていません。"
    lookup_name = name
    if game == "原神":
        lookup_name = GENSHIN_CHARACTER_ALIASES.get(name, name)
    character_title = resolve_character_title(origin, lookup_name)
    if not character_title:
        saved = read_json(character_metadata_path(name), {})
        saved_page = str(saved.get("source_page", "")) if isinstance(saved, dict) else ""
        if saved_page.startswith(origin + "/wiki/"):
            return saved_page, "保存済みの本人ページ情報を使用しました。"
        return "", "対象キャラクター本人を完全一致で特定できませんでした。別キャラクターは採用しません。"
    host = (urlparse(origin).hostname or "").casefold()
    voice_page_candidates = [f"{character_title}/Voice-Overs/Japanese"]
    if host == "wutheringwaves.fandom.com":
        voice_page_candidates.insert(0, f"{character_title}/Voicelines/Japanese")
    if host == "neverness-to-everness.fandom.com":
        voice_page_candidates.append(f"{character_title}/Voice-Overs")

    for normal_title in voice_page_candidates:
        normal_page = query_pages(origin, [normal_title], "info")
        if normal_page and "missing" not in normal_page[0]:
            url = f"{origin}/wiki/{quote(normal_title.replace(' ', '_'), safe='/')}"
            if host == "neverness-to-everness.fandom.com" and normal_title.endswith("/Voice-Overs"):
                return url, (
                    f"本人のVoice-Oversページを検出しました：{normal_title}。"
                    "NTEは日本語音声ファイルの公開状態をまだ確認できていません。"
                )
            return url, f"本人の日本語ボイスページを検出しました：{normal_title}"

    fallback_categories = []
    for category in (
        f"Category:{character_title} Japanese Voicelines",
        f"Category:{character_title} Audio",
        f"Category:{character_title} Voice-Overs",
    ):
        page = query_pages(origin, [category], "info")
        if page and "missing" not in page[0]:
            fallback_categories.append(category)
    if fallback_categories:
        url = f"{origin}/wiki/{quote(character_title.replace(' ', '_'), safe='/')}"
        return url, f"本人の音声カテゴリを検出しました。取得時に日本語Wiki（/ja/）から短い会話音声を選びます：{character_title}"
    return "", "対象キャラクター本人の音声カテゴリを特定できませんでした。別キャラクターは採用しません。"

def parse_template_fields(wikitext: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    key: str | None = None
    parts: list[str] = []
    for raw in str(wikitext).splitlines():
        match = re.match(r"^\s*\|\s*([^=]+?)\s*=\s*(.*)$", raw)
        if match:
            if key is not None:
                fields[key] = "\n".join(parts).strip()
            key = match.group(1).strip()
            parts = [match.group(2).strip()]
        elif key is not None and not re.match(r"^\s*\}\}", raw):
            parts.append(raw.strip())
    if key is not None:
        fields[key] = "\n".join(parts).strip()
    return fields

class VoiceRowParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.rows: list[dict[str, str]] = []
        self.in_row = False
        self.in_th = 0
        self.in_td = 0
        self.jp_depth = 0
        self.files: list[str] = []
        self.title_parts: list[str] = []
        self.transcript_parts: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attributes = dict(attrs)
        if tag == "tr":
            self.in_row = True
            self.files = []
            self.title_parts = []
            self.transcript_parts = []
        elif self.in_row and tag == "th":
            self.in_th += 1
        elif self.in_row and tag == "td":
            self.in_td += 1
        elif self.in_row and tag == "span" and self.in_td and attributes.get("lang") == "ja":
            self.jp_depth += 1
        if self.in_row and tag == "a":
            href = attributes.get("href") or ""
            match = re.search(r"/wiki/File:(.*?\.(?:ogg|oga|wav|mp3|flac))(?=$|[?#])", href, flags=re.I)
            if match:
                filename = unquote(match.group(1)).replace("_", " ")
                if normalized_file_title(filename) not in {normalized_file_title(x) for x in self.files}:
                    self.files.append(filename)

    def handle_endtag(self, tag: str) -> None:
        if tag == "span" and self.jp_depth:
            self.jp_depth -= 1
        elif tag == "th" and self.in_th:
            self.in_th -= 1
        elif tag == "td" and self.in_td:
            self.in_td -= 1
        elif tag == "tr" and self.in_row:
            label = re.sub(r"\s+", " ", " ".join(self.title_parts)).strip()
            transcript = re.sub(r"\s+", " ", " ".join(self.transcript_parts)).strip()
            for filename in self.files:
                self.rows.append({"filename": filename, "label": label or Path(filename).stem, "transcript": transcript})
            self.in_row = False

    def handle_data(self, data: str) -> None:
        text = str(data).strip()
        if not text or not self.in_row:
            return
        if self.in_th:
            self.title_parts.append(text)
        elif self.in_td and self.jp_depth:
            self.transcript_parts.append(text)

def parse_rendered_rows(rendered_html: str) -> list[dict[str, str]]:
    parser = VoiceRowParser()
    parser.feed(str(rendered_html or ""))
    seen: set[str] = set()
    rows: list[dict[str, str]] = []
    for row in parser.rows:
        key = normalized_file_title(row["filename"])
        if key not in seen:
            seen.add(key)
            rows.append(row)
    return rows

def parse_voice_entries(wikitext: str, rendered_html: str) -> list[dict[str, Any]]:
    fields = parse_template_fields(wikitext)
    variables = {
        "language": fields.get("language", "ja").strip(),
        "character": fields.get("character", "").strip(),
        "name": fields.get("name", "").strip(),
    }
    grouped: dict[str, dict[str, str]] = {}
    for key, value in fields.items():
        match = re.match(r"^(vo_[0-9_]+)_(title|subtitle|file|tx)$", key, flags=re.I)
        if match:
            grouped.setdefault(match.group(1), {})[match.group(2).lower()] = value
    entries: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item_id, values in grouped.items():
        raw_file = values.get("file", "")
        for var_name, var_value in variables.items():
            raw_file = raw_file.replace("{" + var_name + "}", var_value)
        filename = plain_wiki_text(raw_file)
        if not re.search(r"\.(ogg|oga|wav|mp3|flac)$", filename, flags=re.I):
            continue
        normalized = filename.replace(" ", "_").casefold()
        if normalized in seen:
            continue
        seen.add(normalized)
        entries.append({
            "id": item_id,
            "file_title": "File:" + filename,
            "filename": filename,
            "label": plain_wiki_text(values.get("title") or values.get("subtitle") or filename),
            "subtitle": plain_wiki_text(values.get("subtitle", "")),
            "transcript": plain_wiki_text(values.get("tx", "")),
        })
    rendered_rows = parse_rendered_rows(rendered_html)
    rendered_files = [row["filename"] for row in rendered_rows]
    rendered_meta = {normalized_file_title(row["filename"]): row for row in rendered_rows}
    if entries:
        # Rendered MediaWiki HTML contains the authoritative File titles after
        # template substitutions such as {language} -> JA_.
        if len(rendered_files) >= len(entries):
            for item, filename in zip(entries, rendered_files):
                item["filename"] = filename
                item["file_title"] = "File:" + filename
        used = {normalized_file_title(item["filename"]) for item in entries}
        for filename in rendered_files:
            key = normalized_file_title(filename)
            if key in used:
                continue
            meta = rendered_meta.get(key, {})
            entries.append({
                "id": f"html_{len(entries):04d}", "file_title": "File:" + filename,
                "filename": filename, "label": plain_wiki_text(meta.get("label", Path(filename).stem)),
                "subtitle": "", "transcript": plain_wiki_text(meta.get("transcript", "")),
            })
            used.add(key)
        return entries
    for filename in rendered_files:
        normalized = filename.replace(" ", "_").casefold()
        if normalized in seen:
            continue
        seen.add(normalized)
        entries.append({
            "id": f"html_{len(entries):04d}", "file_title": "File:" + filename,
            "filename": filename, "label": Path(filename).stem, "subtitle": "", "transcript": "",
        })
    return entries

def normalized_file_title(value: str) -> str:
    return unquote(value).replace(" ", "_").casefold()

def add_file_information(origin: str, entries: list[dict[str, Any]]) -> list[dict[str, Any]]:
    info_map: dict[str, dict[str, Any]] = {}
    for start in range(0, len(entries), 40):
        batch = entries[start:start + 40]
        titles = "|".join(item["file_title"] for item in batch)
        data = api_get(origin, {
            "action": "query", "titles": titles, "prop": "imageinfo",
            "iiprop": "url|size|mime|sha1", "format": "json", "formatversion": 2,
        })
        for page in data.get("query", {}).get("pages", []):
            imageinfo = page.get("imageinfo") or []
            if imageinfo:
                info_map[normalized_file_title(page.get("title", ""))] = imageinfo[0]
    resolved: list[dict[str, Any]] = []
    for item in entries:
        info = info_map.get(normalized_file_title(item["file_title"]))
        if not info:
            continue
        copy = dict(item)
        copy.update({
            "url": info.get("url", ""), "size": int(info.get("size", 0) or 0),
            "mime": info.get("mime", ""), "sha1": info.get("sha1", ""),
        })
        resolved.append(copy)
    return resolved

def read_duration(path: Path) -> float:
    try:
        return round(float(sf.info(str(path)).duration), 3)
    except Exception:
        return 0.0

def unique_destination(folder: Path, filename: str, expected_size: int) -> tuple[Path, bool]:
    base = folder / safe_name(filename, "audio.ogg", 180)
    if not base.exists():
        return base, False
    if base.is_file() and (expected_size <= 0 or base.stat().st_size == expected_size):
        return base, True
    index = 2
    while True:
        candidate = base.with_name(f"{base.stem}_{index}{base.suffix}")
        if not candidate.exists():
            return candidate, False
        if candidate.is_file() and (expected_size <= 0 or candidate.stat().st_size == expected_size):
            return candidate, True
        index += 1

def wait_for_download_backoff() -> None:
    with _download_backoff_lock:
        remaining = _download_backoff_until - time.monotonic()
    if remaining > 0:
        time.sleep(remaining)

def extend_download_backoff(seconds: float) -> None:
    global _download_backoff_until
    with _download_backoff_lock:
        _download_backoff_until = max(_download_backoff_until, time.monotonic() + seconds)

def download_one(folder: Path, item: dict[str, Any], max_attempts: int = 4) -> dict[str, Any]:
    url = str(item.get("url", ""))
    host = (urlparse(url).hostname or "").lower()
    allowed_audio_host = (
        host.endswith("wikia.nocookie.net")
        or host.endswith("fandom.com")
        or host.endswith("huggingface.co")
        or host.endswith("datasets-server.huggingface.co")
    )
    if not allowed_audio_host:
        raise ValueError("許可されていない音声配信元です。")
    destination, duplicate = unique_destination(folder, item["filename"], int(item.get("size", 0)))
    status = "既存ファイルを使用"
    if not duplicate:
        temp = destination.with_suffix(destination.suffix + ".part")
        if host.endswith("huggingface.co"):
            request_headers = {"Accept": "audio/*;q=0.9,*/*;q=0.8"}
        else:
            request_headers = {
                "Referer": str(item.get("download_referer") or item.get("referer", "")),
                "Accept": "audio/ogg,audio/*;q=0.9,*/*;q=0.8",
            }
        last_error: Exception | None = None
        for attempt in range(max_attempts):
            try:
                wait_for_download_backoff()
                digest = hashlib.sha1()
                with SESSION.get(url, stream=True, timeout=90, headers=request_headers) as response:
                    if response.status_code in {403, 429} or response.status_code >= 500:
                        extend_download_backoff(min(12.0, 1.5 * (2 ** attempt)))
                        raise requests.HTTPError(f"HTTP {response.status_code}", response=response)
                    response.raise_for_status()
                    with temp.open("wb") as handle:
                        for chunk in response.iter_content(chunk_size=1024 * 256):
                            if chunk:
                                handle.write(chunk)
                                digest.update(chunk)
                break
            except (requests.RequestException, OSError) as exc:
                last_error = exc
                if attempt + 1 >= max_attempts:
                    raise
                time.sleep(min(12.0, 1.5 * (2 ** attempt)))
        if last_error is not None and not temp.exists():
            raise last_error
        expected_size = int(item.get("size", 0))
        if expected_size and temp.stat().st_size != expected_size:
            raise IOError(f"受信サイズが一致しません：{item['filename']}")
        temp.replace(destination)
        status = "保存済み"
    result = dict(item)
    result.update({"path": str(destination), "duration": read_duration(destination), "status": status})
    return result

def exclusion_reason(item: dict[str, Any]) -> str:
    duration = float(item.get("duration", 0.0) or 0.0)
    reasons: list[str] = []
    if 0 < duration < SHORT_LIMIT:
        reasons.append(f"{SHORT_LIMIT:.1f}秒未満")
    if duration > LONG_LIMIT:
        reasons.append(f"{LONG_LIMIT:.0f}秒超")
    text = " ".join([str(item.get("label", "")), str(item.get("subtitle", "")), str(item.get("transcript", ""))]).casefold()
    if any(word.casefold() in text for word in EXCLUDE_WORDS):
        reasons.append("戦闘声・息遣い等の可能性")
    return "／".join(reasons)

def workers_from_mode(mode: str) -> int:
    text = str(mode or "")
    if "安全" in text:
        return 3
    if "高速" in text:
        return 8
    return 5

