def read_update_status() -> str:
    if not UPDATE_STATUS_PATH.exists():
        return "更新状態：未確認"
    try:
        raw = UPDATE_STATUS_PATH.read_text(encoding="utf-8").strip()
    except Exception:
        return "更新状態：確認できませんでした。"
    if not raw:
        return "更新状態：未確認"
    parts = raw.split("|")
    code = parts[0]
    stamp = parts[1] if len(parts) > 1 else ""
    if code == "REQUESTED":
        return "更新を開始しています…"
    if code == "STARTING":
        try:
            started = datetime.fromisoformat(stamp)
            if (datetime.now() - started).total_seconds() > 10:
                return "更新用プログラムを起動できていません。"
        except Exception:
            pass
        return "更新を開始しています…"
    if code == "CMD_STARTED":
        return "更新用プログラムを起動しました。"
    if code == "JSON_DOWNLOADING":
        return "更新データを取得しています…"
    if code == "APPLYING":
        return "プログラムを更新しています…"
    if code == "RESTARTING":
        return "更新したFandom音声ツールを再起動しています…"
    if code == "SUCCESS":
        when = stamp.replace("T", " ")[:19] if stamp else ""
        return f"更新できました。最新版で起動しています。{(' ' + when) if when else ''}"
    if code == "FAILED":
        reason = parts[2] if len(parts) > 2 else ""
        messages = {
            "JSON_DOWNLOAD": "公開更新データを取得できませんでした。",
            "JSON_PARSE": "取得した更新データを読み取れませんでした。",
            "JSON_FORMAT": "更新データの形式が正しくありません。",
            "ROLLED_BACK": "更新後の起動に失敗したため、直前のプログラムへ戻して起動しました。",
            "ROLLBACK_START": "更新後の起動に失敗し、直前のプログラムへの復旧起動も完了できませんでした。",
            "LAUNCH": "更新用プログラムを起動できませんでした。",
        }
        return "更新に失敗しました。" + messages.get(reason, "更新処理を完了できませんでした。")
    return "更新状態：確認中"


def poll_update_status() -> tuple[str, Any]:
    status = read_update_status()
    code = ""
    try:
        if UPDATE_STATUS_PATH.exists():
            raw = UPDATE_STATUS_PATH.read_text(encoding="utf-8").strip()
            code = raw.split("|", 1)[0] if raw else ""
    except Exception:
        code = ""
    active = code not in {"SUCCESS", "FAILED"}
    return gr.Markdown(value=status, visible=True), gr.Timer(active=active)


def update_and_restart() -> tuple[str, Any]:
    try:
        updater = TOOL_DIR / "update_and_start.ps1"
        if not updater.exists():
            raise FileNotFoundError("update_and_start.ps1 が見つかりません。")

        request_stamp = datetime.now().isoformat(timespec="seconds")
        UPDATE_STATUS_PATH.write_text(
            f"REQUESTED|{request_stamp}\n",
            encoding="ascii",
        )

        windows_updater = subprocess.check_output(
            ["wslpath", "-w", str(updater)],
            text=True,
            encoding="utf-8",
        ).strip()
        if not windows_updater:
            raise RuntimeError("更新処理のWindowsパスを取得できませんでした。")

        escaped_updater = windows_updater.replace("'", "''")
        launch_command = (
            "$ErrorActionPreference='Stop'; "
            f"$script='{escaped_updater}'; "
            "Start-Process -FilePath 'powershell.exe' "
            "-ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File \"{0}\"' -f $script) "
            "-WorkingDirectory (Split-Path -Parent $script) "
            "-WindowStyle Hidden"
        )
        subprocess.run(
            [
                windows_powershell_executable(),
                "-NoProfile",
                "-NonInteractive",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                launch_command,
            ],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
            timeout=10,
        )
        return gr.Markdown(value="更新しています…", visible=True), gr.Timer(active=True)
    except Exception as exc:
        try:
            fail_stamp = datetime.now().isoformat(timespec="seconds")
            UPDATE_STATUS_PATH.write_text(
                f"FAILED|{fail_stamp}|LAUNCH\n",
                encoding="ascii",
            )
        except Exception:
            pass
        return gr.Markdown(value=f"更新を開始できませんでした：{exc}", visible=True), gr.Timer(active=False)

def save_game(game_name: str, wiki_url: str, editing_name: str | None) -> tuple[Any, Any, str]:
    try:
        name = safe_name(game_name, "", 60)
        if not name:
            raise ValueError("ゲーム名を入力してください。")
        if name in BUILTIN_GAME_WIKIS:
            raise ValueError("標準登録ゲームは編集できません。")
        origin = validate_fandom_origin(str(wiki_url or "").rstrip("/"))
        games = load_custom_games()
        old = str(editing_name or "").strip()
        if old and old not in BUILTIN_GAME_WIKIS and old != name:
            games.pop(old, None)
        games[name] = origin
        save_games(games)
        custom = sorted(games)
        return gr.Dropdown(choices=game_choices(), value=name), gr.Dropdown(choices=custom, value=name), f"ゲーム「{name}」を保存しました。"
    except Exception as exc:
        custom = sorted(load_custom_games())
        return gr.Dropdown(choices=game_choices()), gr.Dropdown(choices=custom), f"エラー：{exc}"


def delete_game(game_name: str) -> tuple[Any, Any, str]:
    try:
        name = str(game_name or "").strip()
        if not name:
            raise ValueError("削除する追加ゲームを選択してください。")
        games = load_custom_games()
        if name not in games:
            raise ValueError("標準登録ゲームまたは未登録のゲームは削除できません。")
        games.pop(name)
        write_json(GAMES_PATH, {"games": games})
        return gr.Dropdown(choices=game_choices(), value="崩壊：スターレイル"), gr.Dropdown(choices=sorted(games)), f"ゲーム登録「{name}」だけを削除しました。取得済み音声やキャラクターデータは残っています。"
    except Exception as exc:
        return gr.Dropdown(choices=game_choices()), gr.Dropdown(choices=sorted(load_custom_games())), f"エラー：{exc}"


def load_game_for_edit(game_name: str) -> tuple[str, str]:
    games = load_custom_games()
    name = str(game_name or "")
    return (name, games.get(name, ""))


def speaker_names() -> list[str]:
    return sorted(load_registry().get("speakers", {}).keys())


def speaker_choices() -> list[tuple[str, str]]:
    registry = load_registry().get("speakers", {})
    if not isinstance(registry, dict):
        return []

    game_wikis = all_game_wikis()
    host_to_game = {
        (urlparse(str(url)).hostname or "").casefold(): str(game_name)
        for game_name, url in game_wikis.items()
    }
    grouped: dict[str, list[str]] = {}

    for character in sorted(registry):
        record = registry.get(character, {})
        game_name = ""
        if isinstance(record, dict):
            game_name = str(record.get("game_name", "")).strip()
            if not game_name:
                source_page = str(record.get("source_page", "")).strip()
                host = (urlparse(source_page).hostname or "").casefold()
                game_name = host_to_game.get(host, "")
        if not game_name:
            game_name = "作品未設定"
        grouped.setdefault(game_name, []).append(str(character))

    preferred_order = list(game_wikis)
    remaining = sorted(name for name in grouped if name not in preferred_order)
    ordered_games = [name for name in preferred_order if name in grouped] + remaining

    choices: list[tuple[str, str]] = []
    for game_index, game_name in enumerate(ordered_games):
        characters = sorted(grouped.get(game_name, []))
        for character_index, character in enumerate(characters):
            if character_index == 0:
                prefix = "" if game_index == 0 else "\n"
                label = f"{prefix}{game_name}\n　{character}"
            else:
                label = f"　{character}"
            choices.append((label, character))
    return choices


def records_to_table(records: list[dict[str, Any]]) -> list[list[Any]]:
    rows: list[list[Any]] = []
    for item in records:
        reason = exclusion_reason(item)
        item["reason"] = reason
        item["review"] = bool(reason)
        if "selected" not in item:
            item["selected"] = not bool(reason)
        rows.append([
            item["selected"], item["review"], item.get("duration", 0.0), item.get("label", ""),
            item.get("transcript", ""), Path(item.get("path", item.get("filename", ""))).name, reason,
        ])
    return rows


def table_rows(value: Any) -> list[list[Any]]:
    if value is None:
        return []
    if hasattr(value, "values"):
        return value.values.tolist()
    return list(value)


def selected_from_table(value: Any, records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    by_name = {Path(item.get("path", "")).name: item for item in records}
    selected: list[dict[str, Any]] = []
    for row in table_rows(value):
        if len(row) >= 6 and bool(row[0]):
            item = by_name.get(str(row[5]))
            if item:
                selected.append(item)
    return selected


def total_text(value: Any) -> str:
    total = sum(float(row[2] or 0) for row in table_rows(value) if len(row) >= 3 and bool(row[0]))
    count = sum(1 for row in table_rows(value) if row and bool(row[0]))
    return f"選択中：{count}件／合計 {total:.1f} 秒"


def voice_table_payload(records: list[dict[str, Any]], only_review: bool = False) -> tuple[list[list[Any]], list[str]]:
    rows: list[list[Any]] = []
    keys: list[str] = []
    for item in records or []:
        reason = exclusion_reason(item)
        item["reason"] = reason
        item["review"] = bool(reason)
        if "selected" not in item:
            item["selected"] = not bool(reason)
        if only_review and not item["review"]:
            continue
        filename = Path(str(item.get("path", item.get("filename", "")))).name
        transcript = str(item.get("transcript", "")).strip() or "（台詞未取得）"
        label = str(item.get("label", "")).strip() or Path(filename).stem
        rows.append([
            bool(item.get("selected")),
            "⚠" if item.get("review") else "",
            "▶",
            round(float(item.get("duration", 0.0) or 0.0), 1),
            transcript,
            label,
            reason,
        ])
        keys.append(filename)
    return rows, keys


def update_selection_from_voice_table(
    value: Any,
    visible_keys: list[str],
    records: list[dict[str, Any]],
    character: str = "",
) -> tuple[list[dict[str, Any]], str]:
    updated = [dict(item) for item in (records or [])]
    by_name = {Path(str(item.get("path", item.get("filename", "")))).name: item for item in updated}
    rows = table_rows(value)
    for index, filename in enumerate(visible_keys or []):
        if index >= len(rows):
            break
        item = by_name.get(str(filename))
        if item is not None and rows[index]:
            item["selected"] = bool(rows[index][0])

    metadata_path = character_metadata_path(character)
    if character and metadata_path.exists():
        metadata = read_json(metadata_path, {})
        if isinstance(metadata, dict):
            metadata["files"] = updated
            metadata["selection_updated_at"] = datetime.now().isoformat(timespec="seconds")
            write_json(metadata_path, metadata)
    return updated, total_text(records_to_table(updated))


def play_voice_table_cell(visible_keys: list[str], records: list[dict[str, Any]], evt: gr.SelectData):
    index = evt.index
    if not isinstance(index, (list, tuple)) or len(index) != 2:
        return gr.skip(), gr.skip()
    row_index, column_index = int(index[0]), int(index[1])
    if column_index != 2 or row_index < 0 or row_index >= len(visible_keys or []):
        return gr.skip(), gr.skip()
    filename = str((visible_keys or [])[row_index])
    item = next(
        (entry for entry in (records or []) if Path(str(entry.get("path", entry.get("filename", "")))).name == filename),
        None,
    )
    if not item:
        return gr.skip(), "音声が見つかりません。"
    path = str(item.get("path", ""))
    if not path or not Path(path).exists():
        return gr.skip(), "音声ファイルが見つかりません。"
    caption = str(item.get("transcript", "")).strip() or str(item.get("label", "")).strip() or filename
    return path, f"再生中：{caption}"



