    )


def reference_editor_payload(records: list[dict[str, Any]]) -> tuple[list[list[Any]], str, int]:
    """Build an editable ordering table for the final reference set."""
    rows: list[list[Any]] = []
    selected_seconds = 0.0
    selected_count = 0
    for order, item in enumerate(records or [], start=1):
        filename = Path(str(item.get("path", item.get("filename", "")))).name
        duration = float(item.get("duration", 0.0) or 0.0)
        selected = bool(item.get("selected", True))
        if selected:
            selected_count += 1
            selected_seconds += duration
        rows.append([
            selected,
            order,
            "▶",
            round(duration, 1),
            str(item.get("transcript", "")).strip() or "（台詞未取得）",
            str(item.get("label", "")).strip() or Path(filename).stem,
            filename,
        ])

    used = min(selected_seconds, 120.0)
    tail = max(0.0, selected_seconds - 120.0)
    status = (
        f"使用予定：{selected_count}件／合計 {selected_seconds:.1f}秒。"
        f" 参照セットは上から順に最大120秒を使います。"
    )
    if tail > 0:
        status += f" 120秒を超える末尾 {tail:.1f}秒分は参照セットには入りません。"
    elif selected_seconds < 120.0:
        status += f" あと {120.0 - selected_seconds:.1f}秒まで追加できます。"
    return rows, status, -1


def reference_editor_select(
    value: Any,
    records: list[dict[str, Any]],
    evt: gr.SelectData,
):
    rows = table_rows(value)
    index = evt.index
    if not isinstance(index, (list, tuple)) or len(index) != 2:
        return gr.skip(), gr.skip(), -1
    row_index, column_index = int(index[0]), int(index[1])
    if row_index < 0 or row_index >= len(rows):
        return gr.skip(), gr.skip(), -1

    row = rows[row_index]
    filename = str(row[6]) if len(row) >= 7 else ""
    item = next(
        (
            entry for entry in (records or [])
            if Path(str(entry.get("path", entry.get("filename", "")))).name == filename
        ),
        None,
    )

    row_label = str(row[4] if len(row) > 4 else filename)
    if column_index != 2:
        return gr.skip(), f"編集対象：{row_index + 1}番　{row_label}", row_index

    if not item:
        return gr.skip(), "音声が見つかりません。", row_index
    path = str(item.get("path", ""))
    if not path or not Path(path).exists():
        return gr.skip(), "音声ファイルが見つかりません。", row_index
    caption = str(item.get("transcript", "")).strip() or str(item.get("label", "")).strip() or filename
    return path, f"再生中：{caption}", row_index


def move_reference_row(value: Any, selected_row: int, direction: int) -> tuple[list[list[Any]], int, str]:
    rows = [list(row) for row in table_rows(value)]
    if not rows:
        return rows, -1, "並び替える音声がありません。"
    try:
        current = int(selected_row)
    except (TypeError, ValueError):
        current = -1
    if current < 0 or current >= len(rows):
        return rows, -1, "先に移動したい行をクリックしてください。"

    target = current + int(direction)
    if target < 0 or target >= len(rows):
        return rows, current, "これ以上は移動できません。"

    rows[current], rows[target] = rows[target], rows[current]
    for index, row in enumerate(rows, start=1):
        if len(row) >= 2:
            row[1] = index
    return rows, target, f"{target + 1}番へ移動しました。最後に「順番・使用設定を保存」を押してください。"


def move_reference_row_up(value: Any, selected_row: int):
    return move_reference_row(value, selected_row, -1)


def move_reference_row_down(value: Any, selected_row: int):
    return move_reference_row(value, selected_row, 1)


def apply_reference_editor(
    value: Any,
    records: list[dict[str, Any]],
    character: str,
) -> tuple[list[dict[str, Any]], str, str, int]:
    rows = table_rows(value)
    if not rows:
        return records or [], total_text(records_to_table(records or [])), "保存する設定がありません。", -1

    by_name = {
        Path(str(item.get("path", item.get("filename", "")))).name: dict(item)
        for item in (records or [])
    }
    ordered: list[dict[str, Any]] = []
    seen: set[str] = set()

    for row in rows:
        if len(row) < 7:
            continue
        filename = str(row[6])
        item = by_name.get(filename)
        if not item or filename in seen:
            continue
        item["selected"] = bool(row[0])
        ordered.append(item)
        seen.add(filename)

    # Keep any record that was not visible in the editor, without deleting it.
    for item in (records or []):
        filename = Path(str(item.get("path", item.get("filename", "")))).name
        if filename not in seen:
            ordered.append(dict(item))

    metadata_path = character_metadata_path(character)
    if character and metadata_path.exists():
        metadata = read_json(metadata_path, {})
        if isinstance(metadata, dict):
            metadata["files"] = ordered
            metadata["reference_order_updated_at"] = datetime.now().isoformat(timespec="seconds")
            write_json(metadata_path, metadata)

    selected = [item for item in ordered if bool(item.get("selected", True))]
    seconds = sum(float(item.get("duration", 0.0) or 0.0) for item in selected)
    status = (
        f"保存しました。使用予定 {len(selected)}件／合計 {seconds:.1f}秒。"
        " 事前計算ではこの並び順の先頭から最大120秒を使います。"
    )
    if seconds > 120.0:
        status += f" 末尾 {seconds - 120.0:.1f}秒分は120秒セットには入りません。"
    return ordered, total_text(records_to_table(ordered)), status, -1


def preview_html(records: list[dict[str, Any]]) -> str:
    if not records:
        return "<p>音声はまだありません。</p>"
    cards: list[str] = []
    for item in records:
        path = str(item.get("path", ""))
        source = "/gradio_api/file=" + quote(path, safe="/:")
        reason = exclusion_reason(item)
        badge = f'<span style="color:#b45309">要確認：{html.escape(reason)}</span>' if reason else '<span style="color:#15803d">通常候補</span>'
        cards.append(
            '<div style="border:1px solid #d1d5db;border-radius:8px;padding:10px;margin:8px 0">'
            f'<div><strong>{html.escape(str(item.get("label", "")))}</strong>　{float(item.get("duration", 0)):.1f}秒　{badge}</div>'
            f'<div style="margin:5px 0;color:#374151">{html.escape(str(item.get("transcript", "")))}</div>'
            f'<audio controls preload="none" src="{source}" style="width:100%"></audio></div>'
        )
    return "".join(cards)


def fetch_and_save(
    page_url: str,
    character: str,
    parallel_mode: str = "標準（5並列）",
    progress: gr.Progress = gr.Progress(track_tqdm=False),
) -> tuple[Any, ...]:
    try:
        ensure_dirs()
        char_name = safe_name(character, "キャラクター")
        progress(0.03, desc="ページ確認中")
        origin, page_title = page_parts(page_url)
        source_mode = "voice_page"
        host = (urlparse(origin).hostname or "").casefold()
        is_japanese_voice_page = (
            "/Voice-Overs/Japanese" in page_title
            or "/Voicelines/Japanese" in page_title
        )
        if host == "neverness-to-everness.fandom.com" and page_title.endswith("/Voice-Overs"):
            raise RuntimeError(
                "NTEのFandomにはVoice-Oversページがありますが、日本語音声ファイルをまだ確認できていません。"
                "英語音声を誤取得しないため、現時点では自動取得を止めています。"
            )
        if is_japanese_voice_page:
            parsed = api_get(origin, {
                "action": "parse", "page": page_title, "prop": "wikitext|text",
                "format": "json", "formatversion": 2,
            }).get("parse", {})
            progress(0.10, desc="音声一覧解析中")
            entries = parse_voice_entries(parsed.get("wikitext", ""), parsed.get("text", ""))
            progress(0.16, desc="音声URL取得中")
            entries = add_file_information(origin, entries)
        else:
            source_mode = "character_files"
            progress(0.10, desc="本人の音声カテゴリ確認中")
            entries = fallback_voice_entries(origin, page_title)
            progress(0.16, desc="日本語音声URL取得中")
        for item in entries:
            item["referer"] = page_url
        fallback_status = get_last_fallback_status()
        scan_info = get_last_hf_scan_info()
        if not entries:
            detail = fallback_status if source_mode == "character_files" else ""
            raise RuntimeError(
                "日本語音声候補を取得できませんでした。"
                + (f" {detail}" if detail else " ページURLを確認してください。")
            )
        folder = downloaded_audio_dir(char_name)
        folder.mkdir(parents=True, exist_ok=True)
        records: list[dict[str, Any]] = []
        errors: list[str] = []
        total_entries = len(entries)
        workers = workers_from_mode(parallel_mode)
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            futures = {pool.submit(download_one, folder, item): item for item in entries}
            for completed, future in enumerate(concurrent.futures.as_completed(futures), start=1):
                try:
                    records.append(future.result())
                except Exception as exc:
                    errors.append(f"{futures[future].get('filename', '不明')}: {exc}")
                progress((completed, total_entries), desc=f"音声保存中 {completed} / {total_entries}（{workers}並列）")
        order = {item["file_title"]: index for index, item in enumerate(entries)}
        records.sort(key=lambda item: order.get(item.get("file_title", ""), 999999))
        progress(0.92, desc="音声時間確認中")
        table = records_to_table(records)
        progress(0.97, desc="要確認判定中")
        metadata_path = folder / "音声一覧.json"
        previous = read_json(metadata_path, {})
        previous_files = previous.get("files", []) if isinstance(previous, dict) else []
        if previous_files and not saved_records_match_page(previous_files, page_url):
            archive = folder / f"音声一覧_旧_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
            shutil.copy2(metadata_path, archive)
        previous_selection = {
            normalized_file_title(str(item.get("filename") or Path(str(item.get("path", ""))).name)): bool(item.get("selected"))
            for item in previous_files if isinstance(item, dict) and "selected" in item
        }
        for item in records:
            key = normalized_file_title(str(item.get("filename") or Path(str(item.get("path", ""))).name))
            if key in previous_selection:
                item["selected"] = previous_selection[key]
        table = records_to_table(records)
        metadata = {
            "character": char_name, "source_page": page_url, "page_title": page_title,
            "source_mode": source_mode,
            "source_revision": FALLBACK_SOURCE_REVISION if source_mode == "character_files" else "",
            "updated_at": datetime.now().isoformat(timespec="seconds"), "files": records,
            "download_errors": [str(error) for error in errors],
        }
        if (
            source_mode == "character_files"
            and str(scan_info.get("speaker", "")).casefold() == "paimon"
        ):
            metadata["source_candidate_limit"] = int(scan_info.get("candidate_limit", 100) or 100)
            metadata["source_scanned_rows"] = int(scan_info.get("scanned_rows", 0) or 0)
        write_json(metadata_path, metadata)

        shared_result_status = ""
        if (
            source_mode == "character_files"
            and str(scan_info.get("speaker", "")).casefold() == "paimon"
            and records
        ):
            progress(0.98, desc="A用の分析結果を作成中")
            try:
                build_and_publish_paimon_result(char_name, records, errors, scan_info, HF_GENSHIN_DATASET)
                shared_result_status = " A用の分析結果をshared_results/paimon.jsonへ保存しました。"
            except Exception as exc:
                shared_result_status = f" A用の分析結果を保存できませんでした：{exc}"

        status = f"{len(records)}件を確認しました。新規保存と既存ファイルの再利用を自動判定しました。"
        if source_mode == "character_files":
            total_duration = sum(float(item.get("duration", 0.0) or 0.0) for item in records)
            with_text_count = sum(1 for item in records if str(item.get("transcript", "")).strip())
            status += (
                f" {fallback_status}。"
                f" 保存成功 {len(records)}件／台詞あり {with_text_count}件／"
                f"実音声合計 {total_duration:.1f}秒。"
                " 日本語音声データセットから保存しました。"
            )
        status += shared_result_status
        if errors:
            status += f" 取得失敗：{len(errors)}件。" + "／".join(errors[:3])
        progress(1.0, desc="完了")
        return table, preview_html(records), total_text(table), status, records, char_name
    except Exception as exc:
        return [], "<p>音声を表示できません。</p>", "選択中：0件／合計 0.0 秒", f"エラー：{exc}", [], character


def voice_page_owner(url: str) -> str:
    path = unquote(urlparse(str(url or "")).path)
    match = re.search(r"/wiki/([^/]+)(?:/Voice-Overs/Japanese)?$", path.rstrip("/"), re.I)
    return normalized_words(match.group(1).replace("_", " ")) if match else ""


def saved_records_match_page(records: list[dict[str, Any]], expected_page: str) -> bool:
    expected_owner = voice_page_owner(expected_page)
    if not expected_owner:
        return True
    owners = {voice_page_owner(str(item.get("referer", ""))) for item in records}
    owners.discard("")
    return not owners or owners == {expected_owner}


def load_saved_records(character: str, expected_page: str = "") -> tuple[list[dict[str, Any]], str, str]:
    name = safe_name(character, "")
    if not name:
        return [], "", "キャラクター名を入力してください。"
    path = character_metadata_path(name)
    if not path.exists():
        return [], "", "保存済み一覧はありません。初回取得を行います。"
    data = read_json(path, {})
    if (
        isinstance(data, dict)
        and data.get("source_mode") == "character_files"
        and data.get("source_revision") != FALLBACK_SOURCE_REVISION
    ):
        return [], str(data.get("source_page", "")), "取得元を日本語音声データセットへ更新したため、古い一覧は使用しません。"
    if (
        is_paimon_character(name)
        and isinstance(data, dict)
        and data.get("source_mode") == "character_files"
        and int(data.get("source_candidate_limit", 0) or 0) < 100
    ):
        return [], str(data.get("source_page", "")), "既存音声を再利用しながら100件上限へ拡張します。"
    records = data.get("files", []) if isinstance(data, dict) else []
    valid: list[dict[str, Any]] = []
    for item in records:
        if isinstance(item, dict) and item.get("path") and Path(item["path"]).exists():
            valid.append(item)
    if valid and not saved_records_match_page(valid, expected_page):
        return [], "", "保存済み一覧は別キャラクターの内容だったため使用しません。"
    records_to_table(valid)
    source_page = str(data.get("source_page", "")) if isinstance(data, dict) else ""
    return valid, source_page, f"保存済み一覧をローカルから表示しました：{len(valid)}件（ネット接続なし）"


def collect_or_load(
    page_url: str,
    character: str,
    parallel_mode: str,
    force_refresh: bool = False,
    progress: gr.Progress = gr.Progress(track_tqdm=False),
) -> tuple[list[dict[str, Any]], str, str, str]:
    saved, saved_page, saved_status = load_saved_records(character, page_url)
    if saved and not force_refresh:
        if is_paimon_character(character):
            published = read_json(PAIMON_SHARED_PUBLISHED_PATH, {})
            shared_ready = (
                isinstance(published, dict)
                and published.get("status") == "ready"
                and int(published.get("candidate_count", -1)) == len(saved)
            )
            if not shared_ready:
                metadata = read_json(character_metadata_path(character), {})
                saved_errors = metadata.get("download_errors", []) if isinstance(metadata, dict) else []
                try:
                    build_and_publish_paimon_result(character, saved, list(saved_errors or []))
                    saved_status += " A用の分析結果もshared_results/paimon.jsonへ保存しました。"
                except Exception as exc:
                    saved_status += f" A用の分析結果を保存できませんでした：{exc}"
        return saved, total_text(records_to_table(saved)), saved_status, saved_page or page_url
    effective_url = str(page_url or saved_page).strip()
    if not effective_url:
        return [], "選択中：0件／合計 0.0 秒", "ページを自動検出してください。", ""
    table, _preview, total, status, records, _name = fetch_and_save(
        effective_url, character, parallel_mode, progress
    )
    return records, total, status, effective_url


