def manual_add_files(
    files: Any,
    records: list[dict[str, Any]],
    character: str,
) -> tuple[list[dict[str, Any]], str, Any]:
    updated = [dict(item) for item in (records or [])]
    char_name = safe_name(character, "", 80)
    if not char_name:
        return updated, "キャラクター名を入力してから音声を追加してください。", None

    if files is None:
        incoming: list[Any] = []
    elif isinstance(files, (str, Path)):
        incoming = [files]
    else:
        incoming = list(files)

    if not incoming:
        return updated, "追加する音声を選択してください。", None

    target_dir = manual_audio_dir(char_name)
    target_dir.mkdir(parents=True, exist_ok=True)
    allowed = {".wav", ".ogg", ".oga", ".mp3", ".flac"}
    added = 0

    for value in incoming:
        source = Path(str(getattr(value, "name", value)))
        if not source.exists() or not source.is_file():
            continue
        if source.suffix.casefold() not in allowed:
            continue

        destination = unused_path(target_dir / safe_name(source.name, "audio.wav", 180))
        shutil.copy2(source, destination)
        updated.append({
            "id": f"manual_{datetime.now().strftime('%Y%m%d%H%M%S%f')}_{added}",
            "file_title": destination.name,
            "filename": destination.name,
            "original_filename": source.name,
            "label": source.name,
            "subtitle": "",
            "transcript": "",
            "path": str(destination),
            "duration": read_duration(destination),
            "status": "手持ち音声",
            "selected": True,
            "review": False,
            "reason": "",
        })
        added += 1

    if not added:
        return updated, "対応する音声ファイルを追加できませんでした。", None
    return updated, f"{added}件追加しました。合計{len(updated)}件です。", None


def auto_create_from_records(
    character: str,
    records: list[dict[str, Any]],
    page_url: str,
):
    if not _auto_create_lock.acquire(blocking=False):
        yield (
            "<div class='status-working'><strong>キャラクター作成はすでに実行中です。</strong></div>",
            gr.Button("作成中…", variant="primary", interactive=False, elem_classes=["action-primary"]),
            gr.skip(),
            gr.skip(),
            gr.skip(),
        )
        return

    events: queue.Queue[tuple[str, Any]] = queue.Queue()

    def report_progress(message: str) -> None:
        events.put(("progress", str(message)))

    def worker() -> None:
        try:
            result = auto_create_character_references(
                character,
                records or [],
                page_url,
                TARGET_SECONDS,
                progress_callback=report_progress,
            )
            events.put(("done", result))
        except Exception as exc:
            events.put(("error", exc))

    try:
        yield (
            "<div class='status-working'><strong>キャラクター作成を開始しました</strong></div>",
            gr.Button("作成中…", variant="primary", interactive=False, elem_classes=["action-primary"]),
            gr.skip(),
            gr.skip(),
            gr.skip(),
        )

        threading.Thread(
            target=worker,
            name="auto-character-create",
            daemon=True,
        ).start()

        while True:
            kind, payload = events.get()

            if kind == "progress":
                yield (
                    f"<div class='status-working'><strong>{html.escape(str(payload))}</strong></div>",
                    gr.Button("作成中…", variant="primary", interactive=False, elem_classes=["action-primary"]),
                    gr.skip(),
                    gr.skip(),
                    gr.skip(),
                )
                continue

            if kind == "error":
                yield (
                    f"<div class='status-error'><strong>エラー：</strong>{html.escape(str(payload))}</div>",
                    gr.Button("⑤ キャラクターを作成", variant="primary", interactive=True, elem_classes=["action-primary"]),
                    gr.skip(),
                    gr.skip(),
                    gr.skip(),
                )
                return

            char_name, sets, summary = payload
            names = speaker_choices()
            details = "、".join(
                f"{sec}秒枠={sets[str(sec)]['actual_seconds']:.1f}秒"
                for sec in TARGET_SECONDS
            )
            dedicated = "・".join(summary.get("dedicated_emotions", [])) or "なし"
            fallback = "・".join(summary.get("fallback_emotions", [])) or "なし"
            status = (
                "<div class='status-success'>"
                f"<strong>完了</strong>　キャラクター「{html.escape(char_name)}」を自動作成しました。<br>"
                f"{html.escape(details)}<br>"
                f"感情専用参照：{html.escape(dedicated)}<br>"
                f"標準参照へフォールバック：{html.escape(fallback)}"
                "</div>"
            )
            dropdown = gr.Dropdown(choices=names, value=char_name)
            yield (
                status,
                gr.Button("⑤ キャラクターを作成", variant="primary", interactive=True, elem_classes=["action-primary"]),
                dropdown,
                dropdown,
                dropdown,
            )
            return
    finally:
        _auto_create_lock.release()


