def _emotion_slot_updates(mix: dict[str, Any] | None) -> tuple[Any, ...]:
    normalized = normalize_emotion_mix(mix)
    items = list(normalized.items())
    updates: list[Any] = []
    for index in range(3):
        if index < len(items):
            key, value = items[index]
            updates.append(
                gr.Slider(
                    value=int(round(value)),
                    minimum=0,
                    maximum=100,
                    step=1,
                    label=f"感情{index + 1}：{EMOTION_UI_LABELS[key]}",
                    interactive=True,
                )
            )
        else:
            updates.append(
                gr.Slider(
                    value=0,
                    minimum=0,
                    maximum=100,
                    step=1,
                    label=f"感情{index + 1}：― 未選択 ―",
                    interactive=False,
                )
            )
    return tuple(updates)


