    normalized = normalize_emotion_mix(mix)
    caption = (
        emotion_mix_caption(character, normalized)
        if normalized
        else load_default_caption(character)
    )
    status = status_override or emotion_mix_status(character, normalized)
    return (
        normalized,
        caption,
        status,
        *_emotion_button_updates(normalized),
        *_emotion_slot_updates(normalized),
    )


def _initial_emotion_mix(keys: list[str]) -> dict[str, float]:
    selected = [key for key in keys if key in EMOTION_UI_KEYS][:3]
    if not selected:
        return {}
    if len(selected) == 1:
        weights = [100.0]
    elif len(selected) == 2:
        weights = [50.0, 50.0]
    else:
        weights = [34.0, 33.0, 33.0]
    return {
        key: weight
        for key, weight in zip(selected, weights)
    }


def clear_emotion_mix(character: str) -> tuple[Any, ...]:
    return _emotion_mix_payload(character, {})


def toggle_emotion_mix(
    character: str,
    current_mix: dict[str, Any] | None,
    emotion_key: str,
) -> tuple[Any, ...]:
    normalized = normalize_emotion_mix(current_mix)
    key = str(emotion_key or "").strip()
    if key not in EMOTION_UI_KEYS:
        return _emotion_mix_payload(character, normalized)

    selected = list(normalized)
    if key in selected:
        selected = [name for name in selected if name != key]
    else:
        if len(selected) >= 3:
            return _emotion_mix_payload(
                character,
                normalized,
                "感情は最大3つまで選択できます。",
            )
        selected.append(key)

    return _emotion_mix_payload(character, _initial_emotion_mix(selected))


def adjust_emotion_slot(
    character: str,
    current_mix: dict[str, Any] | None,
    slot_index: int,
    requested_value: float,
) -> tuple[Any, ...]:
    normalized = normalize_emotion_mix(current_mix)
    items = list(normalized.items())
    index = int(slot_index)
    if index < 0 or index >= len(items):
        return _emotion_mix_payload(character, normalized)

    requested = max(0, min(100, int(round(float(requested_value or 0)))))
    keys = [key for key, _value in items]
    values = [int(round(float(value))) for _key, value in items]

    if len(items) == 1:
        updated_values = [100]
    elif len(items) == 2:
        if index == 0:
            updated_values = [requested, 100 - requested]
        else:
            updated_values = [100 - requested, requested]
    else:
        if index == 0:
            remaining = 100 - requested
            other_total = max(0, values[1]) + max(0, values[2])
            if other_total <= 0:
                second = remaining // 2
            else:
                second = int(round(remaining * max(0, values[1]) / other_total))
            second = max(0, min(remaining, second))
            updated_values = [requested, second, remaining - second]
        elif index == 1:
            first = max(0, min(100 - requested, values[0]))
            updated_values = [first, requested, 100 - first - requested]
        else:
            first = max(0, min(100 - requested, values[0]))
            updated_values = [first, 100 - first - requested, requested]

    updated = {
        key: float(value)
        for key, value in zip(keys, updated_values)
        if value > 0
    }
    return _emotion_mix_payload(character, updated)


