def load_pronunciation_dictionary() -> dict[str, str]:
    data = load_dictionary_data()
    common = data.get("common", {}) if isinstance(data, dict) else {}
    return {str(k): str(v) for k, v in common.items()}


def dictionary_for(scope: str, character: str) -> dict[str, str]:
    if str(scope).startswith("キャラクター別"):
        speaker = load_registry().get("speakers", {}).get(str(character or ""), {})
        values = speaker.get("pronunciation", {}) if isinstance(speaker, dict) else {}
        return {str(k): str(v) for k, v in values.items()}
    return load_pronunciation_dictionary()


def dictionary_dropdown(scope: str, character: str) -> Any:
    values = dictionary_for(scope, character)
    choices = [(f"{key} → {value}", key) for key, value in sorted(values.items())]
    return gr.Dropdown(choices=choices, value=choices[0][1] if choices else None)


def load_dictionary_entry(scope: str, character: str, word: str) -> tuple[str, str]:
    key = str(word or "")
    return key, dictionary_for(scope, character).get(key, "")


def save_pronunciation(scope: str, character: str, word: str, reading: str) -> tuple[str, Any]:
    key = str(word or "").strip()
    value = str(reading or "").strip()
    if not key or not value:
        return "エラー：固有名詞と読み方を入力してください。", dictionary_dropdown(scope, character)
    if str(scope).startswith("キャラクター別"):
        name = str(character or "").strip()
        registry = load_registry()
        speaker = registry.get("speakers", {}).get(name)
        if not isinstance(speaker, dict):
            return "エラー：キャラクターを選択してください。", dictionary_dropdown(scope, character)
        speaker.setdefault("pronunciation", {})[key] = value
        save_registry(registry)
    else:
        common = load_pronunciation_dictionary()
        common[key] = value
        save_dictionary_data({"common": common})
    return f"「{key} → {value}」を保存しました。", dictionary_dropdown(scope, character)


def delete_pronunciation(scope: str, character: str, word: str) -> tuple[str, Any]:
    key = str(word or "").strip()
    if not key:
        return "削除する登録を選択してください。", dictionary_dropdown(scope, character)
    if str(scope).startswith("キャラクター別"):
        registry = load_registry()
        speaker = registry.get("speakers", {}).get(str(character or ""), {})
        values = speaker.get("pronunciation", {}) if isinstance(speaker, dict) else {}
        values.pop(key, None)
        save_registry(registry)
    else:
        values = load_pronunciation_dictionary()
        values.pop(key, None)
        save_dictionary_data({"common": values})
    return f"辞書登録「{key}」だけを削除しました。音声データには影響しません。", dictionary_dropdown(scope, character)


def reuse_history(history_id: str) -> tuple[Any, ...]:
    item = next((x for x in load_history() if x.get("id") == history_id), None)
    if not item:
        empty_buttons = _emotion_button_updates({})
        return (
            gr.Dropdown(choices=speaker_choices()),
            "",
            "",
            120,
            {},
            *empty_buttons,
            *_emotion_slot_updates({}),
            "標準：通常の参照秒数を使います。",
            4.0,
            False,
            "通常",
            5.0,
            False,
            1.15,
            "履歴を選択してください。",
        )

    mix = item.get("emotion_mix", {})
    if not isinstance(mix, dict) or not mix:
        old_key = str(item.get("emotion_key", "")).strip()
        mix = {old_key: 100.0} if old_key in EMOTION_UI_KEYS else {}
    normalized = normalize_emotion_mix(mix)
    character = str(item.get("character", ""))
    seconds = 120 if normalized else int(item.get("ref_seconds", 120))
    raw_kv = item.get("speaker_kv_scale")
    kv_enabled = raw_kv is not None
    try:
        kv_value = float(raw_kv) if raw_kv is not None else 1.15
    except (TypeError, ValueError):
        kv_value = 1.15

    return (
        gr.Dropdown(choices=speaker_choices(), value=character),
        str(item.get("text", "")),
        str(item.get("caption", "")),
        seconds,
        normalized,
        *_emotion_button_updates(normalized),
        *_emotion_slot_updates(normalized),
        emotion_mix_status(character, normalized),
        float(item.get("cfg_scale_caption", 4.0) or 4.0),
        bool(item.get("emoji_enabled", False)),
        str(item.get("emoji_strength", "通常") or "通常"),
        float(item.get("cfg_scale_speaker", 5.0) or 5.0),
        kv_enabled,
        kv_value,
        "履歴の設定を入力欄へ復元しました。",
    )


def source_mode_visibility(mode: str) -> tuple[Any, Any]:
    use_site = str(mode or "") != "手持ち音声を使う"
    return (
        gr.Column(visible=use_site),
        gr.Column(visible=not use_site),
    )


def add_result_card_to_join(
    result_id: int,
    join_records: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], str]:
    staged_path, status = stage_generation_result_for_join(int(result_id))
    if not staged_path:
        return join_records or [], status
    updated, join_status = add_generated_to_join(staged_path, join_records or [])
    return updated, join_status


def save_generation_result_ui(result_id: int) -> tuple[str, list[list[Any]], Any, str]:
    _items, history, choice, status = save_generation_result(int(result_id))
    return generation_results_render_token(), history, choice, status


def discard_generation_result_ui(result_id: int) -> tuple[str, str]:
    _items, status = discard_generation_result(int(result_id))
    return generation_results_render_token(), status


