from __future__ import annotations

from datetime import datetime
from pathlib import Path
from typing import Any

import gradio as gr
import numpy as np
import soundfile as sf

from paths import JOIN_OUTPUT_ROOT, join_preview_dir, safe_name


JOIN_SAMPLE_RATE = 48000
JOIN_SUBTYPE = "PCM_16"


def join_upload_path(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        return str(value.get("path") or value.get("name") or "")
    return str(getattr(value, "name", "") or "")


def join_add_files(
    files: Any,
    records: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], str, None]:
    updated = [dict(item) for item in (records or [])]
    values = files if isinstance(files, (list, tuple)) else ([files] if files else [])
    added = 0
    errors: list[str] = []
    for upload in values:
        path_text = join_upload_path(upload)
        path = Path(path_text)
        if not path_text or not path.exists() or not path.is_file():
            errors.append(Path(path_text).name or "不明なファイル")
            continue
        try:
            info = sf.info(str(path))
        except Exception:
            errors.append(path.name)
            continue
        updated.append({
            "path": str(path),
            "filename": path.name,
            "duration": float(info.duration),
            "interval": "",
        })
        added += 1
    status = f"{added}件追加しました。合計 {len(updated)}件。"
    if errors:
        status += " 読み込めなかったファイル：" + "、".join(errors[:3])
    return updated, status, None


def add_generated_to_join(
    audio_path: str | None,
    records: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], str]:
    if not audio_path:
        return records or [], "追加できる完成音声がありません。"
    updated, status, _clear = join_add_files(audio_path, records)
    return updated, status


def join_set_interval(value: Any, records: list[dict[str, Any]], index: int) -> tuple[list[dict[str, Any]], str]:
    updated = [dict(item) for item in (records or [])]
    if index < 0 or index >= len(updated):
        return updated, "対象の音声が見つかりません。"
    if value is None or str(value).strip() == "":
        updated[index]["interval"] = ""
        return updated, "個別間隔を解除しました。標準間隔を使用します。"
    try:
        seconds = max(0.0, round(float(value) * 10.0) / 10.0)
    except (TypeError, ValueError):
        return updated, "間隔は0.1秒単位の数字で指定してください。"
    updated[index]["interval"] = seconds
    return updated, f"{updated[index].get('filename', '')} の後の間隔を {seconds:.1f}秒にしました。"


def join_play_record(records: list[dict[str, Any]], index: int):
    if index < 0 or index >= len(records or []):
        return gr.skip(), "対象の音声が見つかりません。"
    item = (records or [])[index]
    path = str(item.get("path", ""))
    if not path or not Path(path).exists():
        return gr.skip(), "音声ファイルが見つかりません。"
    return path, f"再生中：{item.get('filename', '')}"


def move_join_record(records: list[dict[str, Any]], index: int, direction: int) -> tuple[list[dict[str, Any]], str]:
    updated = [dict(item) for item in (records or [])]
    if index < 0 or index >= len(updated):
        return updated, "対象の音声が見つかりません。"
    target = index + int(direction)
    if target < 0 or target >= len(updated):
        return updated, "これ以上は移動できません。"
    updated[index], updated[target] = updated[target], updated[index]
    return updated, f"{target + 1}番へ移動しました。"


def delete_join_record(records: list[dict[str, Any]], index: int) -> tuple[list[dict[str, Any]], str]:
    updated = [dict(item) for item in (records or [])]
    if index < 0 or index >= len(updated):
        return updated, "対象の音声が見つかりません。"
    removed = updated.pop(index)
    return updated, f"一覧から削除しました：{removed.get('filename', '')}。元ファイルは変更していません。"


def make_join_interval_handler(index: int):
    def handler(value: Any, records: list[dict[str, Any]]):
        return join_set_interval(value, records, index)
    return handler


def make_join_play_handler(index: int):
    def handler(records: list[dict[str, Any]]):
        return join_play_record(records, index)
    return handler


def make_join_move_handler(index: int, direction: int):
    def handler(records: list[dict[str, Any]]):
        return move_join_record(records, index, direction)
    return handler


def make_join_delete_handler(index: int):
    def handler(records: list[dict[str, Any]]):
        return delete_join_record(records, index)
    return handler


def join_interval_seconds(raw: Any, standard: float) -> float:
    if raw is None or str(raw).strip() == "":
        value = float(standard)
    else:
        value = float(raw)
    return max(0.0, round(value * 10.0) / 10.0)


def normalize_join_channels(audio: np.ndarray, target_channels: int) -> np.ndarray:
    data = np.asarray(audio, dtype=np.float32)
    if data.ndim == 1:
        data = data[:, None]
    if data.ndim != 2:
        raise ValueError("音声のチャンネル形式を読み取れません。")
    channels = data.shape[1]
    if target_channels == 1:
        if channels != 1:
            data = data.mean(axis=1, keepdims=True)
        return data
    if channels == 1:
        return np.repeat(data, 2, axis=1)
    if channels == 2:
        return data
    mono = data.mean(axis=1, keepdims=True)
    return np.repeat(mono, 2, axis=1)


def resample_join_audio(audio: np.ndarray, source_rate: int, target_rate: int) -> np.ndarray:
    if int(source_rate) == int(target_rate):
        return np.asarray(audio, dtype=np.float32)
    if source_rate <= 0 or target_rate <= 0 or len(audio) == 0:
        raise ValueError("サンプルレートが不正です。")
    new_length = max(1, int(round(len(audio) * float(target_rate) / float(source_rate))))
    if len(audio) == 1:
        return np.repeat(np.asarray(audio, dtype=np.float32), new_length, axis=0)
    old_x = np.arange(len(audio), dtype=np.float64)
    new_x = np.linspace(0.0, len(audio) - 1, new_length, dtype=np.float64)
    channels = [np.interp(new_x, old_x, audio[:, channel]) for channel in range(audio.shape[1])]
    return np.stack(channels, axis=1).astype(np.float32)


def join_safe_stem(value: str) -> str:
    raw = Path(str(value or "").strip()).stem
    stem = safe_name(raw, "", 120)
    reserved = {"CON", "PRN", "AUX", "NUL", *(f"COM{i}" for i in range(1, 10)), *(f"LPT{i}" for i in range(1, 10))}
    if stem.upper() in reserved:
        stem = "_" + stem
    return stem


def join_output_path(filename: str) -> Path:
    JOIN_OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    stem = join_safe_stem(filename)
    if not stem:
        stem = datetime.now().strftime("結合音声_%Y%m%d_%H%M%S")
    candidate = JOIN_OUTPUT_ROOT / f"{stem}.wav"
    index = 2
    while candidate.exists():
        candidate = JOIN_OUTPUT_ROOT / f"{stem}_{index}.wav"
        index += 1
    return candidate


def build_join_audio(
    records: list[dict[str, Any]],
    standard_interval: float,
) -> tuple[np.ndarray, int]:
    updated = [dict(item) for item in (records or [])]
    if not updated:
        raise ValueError("結合する音声を追加してください。")
    paths = [Path(str(item.get("path", ""))) for item in updated]
    for path in paths:
        if not path.exists() or not path.is_file():
            raise FileNotFoundError(f"音声ファイルが見つかりません：{path}")
    infos = [sf.info(str(path)) for path in paths]
    target_channels = 2 if any(int(info.channels) > 1 for info in infos) else 1
    pieces: list[np.ndarray] = []
    for index, (item, path) in enumerate(zip(updated, paths)):
        audio, source_rate = sf.read(str(path), dtype="float32", always_2d=True)
        audio = normalize_join_channels(audio, target_channels)
        audio = resample_join_audio(audio, int(source_rate), JOIN_SAMPLE_RATE)
        pieces.append(audio)
        if index < len(updated) - 1:
            seconds = join_interval_seconds(item.get("interval", ""), standard_interval)
            silence_frames = int(round(seconds * JOIN_SAMPLE_RATE))
            if silence_frames > 0:
                pieces.append(np.zeros((silence_frames, target_channels), dtype=np.float32))
    return np.concatenate(pieces, axis=0), target_channels


def write_join_wav(output: Path, combined: np.ndarray, target_channels: int) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    write_data = combined[:, 0] if target_channels == 1 else combined
    sf.write(str(output), write_data, JOIN_SAMPLE_RATE, subtype=JOIN_SUBTYPE, format="WAV")


def join_preview_audio(
    records: list[dict[str, Any]],
    standard_interval: float,
) -> tuple[str | None, str]:
    try:
        combined, target_channels = build_join_audio(records, standard_interval)
        preview_dir = join_preview_dir()
        preview_dir.mkdir(parents=True, exist_ok=True)
        output = preview_dir / datetime.now().strftime("preview_%Y%m%d_%H%M%S_%f.wav")
        write_join_wav(output, combined, target_channels)
        duration = len(combined) / JOIN_SAMPLE_RATE
        channel_label = "モノラル" if target_channels == 1 else "ステレオ"
        return str(output), f"試聴用に結合しました。{duration:.1f}秒／48kHz／{channel_label}／16bit WAV"
    except Exception as exc:
        return None, f"エラー：{exc}"


def join_save_audio(
    records: list[dict[str, Any]],
    standard_interval: float,
    output_filename: str,
) -> tuple[str | None, str]:
    try:
        combined, target_channels = build_join_audio(records, standard_interval)
        output = join_output_path(output_filename)
        write_join_wav(output, combined, target_channels)
        return str(output), f"保存しました\n保存先：{output}"
    except Exception as exc:
        return None, f"エラー：{exc}"

