AUTO_MIN_EMOTION_FILES = 2
AUTO_MIN_EMOTION_SECONDS = 6.0
AUTO_EMOTION_SIMILARITY_FLOOR = 0.86


def _standard_reference(character: str, seconds: int = 120) -> tuple[Path, float]:
    requested = int(seconds)
    speaker = load_registry().get("speakers", {}).get(character, {})
    info = speaker.get("sets", {}).get(str(requested)) if isinstance(speaker, dict) else None
    if not isinstance(info, dict) or not info.get("path"):
        raise ValueError(f"標準{requested}秒の参照セットがありません。")
    path = Path(str(info["path"]))
    if not path.is_file():
        raise FileNotFoundError(f"標準{requested}秒の参照セットが見つかりません：{path}")
    actual = float(info.get("actual_seconds", requested) or requested)
    return path, actual


def _character_plan_path(character: str) -> Path:
    return TOOL_DIR / "shared_results" / "emotion_pools" / f"{safe_name(character, 'character')}.json"


def load_emotion_plan(character: str) -> dict[str, Any]:
    name = str(character or "").strip()
    if not name:
        return {}

    candidates = [_character_plan_path(name)]
    if name == "パイモン":
        candidates.append(PAIMON_LEGACY_PLAN_PATH)

    for path in candidates:
        data = read_json(path, {})
        if not isinstance(data, dict):
            continue
        if str(data.get("character", "")) != name:
            continue
        if str(data.get("status", "")) not in READY_STATUSES:
            continue
        return data
    return {}


def _emotion_config(character: str, emotion_key: str) -> tuple[dict[str, Any], dict[str, Any]]:
    key = str(emotion_key or "").strip()
    default = EMOTION_DEFAULTS.get(key)
    if not default:
        raise ValueError("対応していない感情です。")

    plan = load_emotion_plan(character)
    pool = plan.get("emotions", {}).get(key, {}) if isinstance(plan, dict) else {}
    if not isinstance(pool, dict):
        pool = {}

    status = str(pool.get("status", ""))
    if status in READY_STATUSES:
        merged = dict(default)
        merged.update(pool)
        if not str(merged.get("caption", "")).strip():
            merged["caption"] = default["caption"]
        return plan, merged

    if status == "merged_into_standard":
        merged = dict(default)
        merged.update(pool)
        if not str(merged.get("caption", "")).strip():
            merged["caption"] = default["caption"]
        merged["use_standard_reference"] = True
        return plan, merged

    return {}, {
        **default,
        "status": "generic",
        "use_standard_reference": True,
        "total_duration_sec": 120.0,
    }



def _record_filename(item: dict[str, Any]) -> str:
    raw = str(item.get("path", item.get("filename", ""))).strip()
    return Path(raw).name if raw else ""


def _dialogue_text(item: dict[str, Any]) -> str:
    return " ".join(
        str(item.get(key, "") or "")
        for key in ("transcript", "subtitle", "label")
    ).strip().casefold()


def _dialogue_key(item: dict[str, Any]) -> str:
    text = _dialogue_text(item)
    return "".join(character for character in text if character.isalnum())


def _semantic_score(item: dict[str, Any], emotion_key: str) -> float:
    text = _dialogue_text(item)
    score = 0.0
    for token, weight in SEMANTIC_HINTS.get(emotion_key, ()):
        if token.casefold() in text:
            score += float(weight)

    if emotion_key == "surprised":
        if "？" in text or "?" in text:
            score += 0.35
        if ("！" in text or "!" in text) and ("？" in text or "?" in text):
            score += 0.45
    elif emotion_key in {"angry", "cheerful"}:
        if "！" in text or "!" in text:
            score += 0.20
    return score


def _mean_similarity(
    matrix: list[list[float]],
    row_index: int,
    target_indices: list[int],
) -> float:
    values = [
        float(matrix[row_index][target])
        for target in target_indices
        if target != row_index
    ]
    if not values and row_index in target_indices:
        return 1.0
    if not values:
        return 0.0
    values.sort(reverse=True)
    return sum(values[: min(5, len(values))]) / min(5, len(values))


def _centrality(matrix: list[list[float]], row_index: int) -> float:
    values = [
        float(value)
        for index, value in enumerate(matrix[row_index])
        if index != row_index
    ]
    if not values:
        return 1.0
    values.sort(reverse=True)
    count = min(8, len(values))
    return sum(values[:count]) / count


def _percentile(values: list[float], ratio: float) -> float:
    if not values:
        return 0.0
    ordered = sorted(float(value) for value in values)
    position = max(0, min(len(ordered) - 1, int(round((len(ordered) - 1) * ratio))))
    return ordered[position]


def _select_core_records(standard_records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    core: list[dict[str, Any]] = []
    total = 0.0
    for item in standard_records:
        duration = float(item.get("duration", 0.0) or 0.0)
        if duration <= 0:
            continue
        if core and total + duration > 35.0 and total >= 25.0:
            break
        core.append(item)
        total += duration
        if total >= 30.0:
            break
    return core or standard_records[:1]


def _semantic_scores(item: dict[str, Any]) -> dict[str, float]:
    return {
        emotion_key: _semantic_score(item, emotion_key)
        for emotion_key in EMOTION_DEFAULTS
    }


def _take_until_seconds(
    ranked: list[dict[str, Any]],
    maximum_seconds: float = 120.0,
) -> list[dict[str, Any]]:
    chosen: list[dict[str, Any]] = []
    total = 0.0
    seen_dialogue: set[str] = set()
    for item in ranked:
        duration = float(item.get("duration", 0.0) or 0.0)
        if duration <= 0:
            continue
        dialogue_key = _dialogue_key(item)
        if dialogue_key and dialogue_key in seen_dialogue:
            continue
        if total + duration > maximum_seconds:
            continue
        chosen.append(item)
        total += duration
        if dialogue_key:
            seen_dialogue.add(dialogue_key)
        if total >= maximum_seconds:
            break
    return chosen


def _eligible_records(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    eligible: list[dict[str, Any]] = []
    for source in records or []:
        item = dict(source)
        path = Path(str(item.get("path", "")))
        if not path.is_file():
            continue
        duration = float(item.get("duration", 0.0) or 0.0)
        if duration <= 0 or duration < 1.5 or duration > 12.0:
            continue
        if exclusion_reason(item):
            continue
        eligible.append(item)
    return eligible


def auto_create_character_references(
    character: str,
    records: list[dict[str, Any]],
    page_url: str,
    target_seconds: tuple[int, ...] = (30, 60, 90, 120),
    progress_callback: Callable[[str], None] | None = None,
) -> tuple[str, dict[str, Any], dict[str, Any]]:
    def report(message: str) -> None:
        if progress_callback is not None:
            progress_callback(message)

    name = safe_name(character, "キャラクター")
    report("保存済み音声を確認中")
    eligible = _eligible_records(records)
    if not eligible:
        raise ValueError("自動参照セットに使える音声がありません。")

    def report_emotion2vec(done: int, total: int) -> None:
        report(f"emotion2vec分析中（{total}件中 {done}件）")

    report("emotion2vec分析中")
    order, matrix = emotion2vec_similarity_matrix(
        name,
        eligible,
        progress_callback=report_emotion2vec,
    )
    by_filename = {_record_filename(item): item for item in eligible}
    ordered = [by_filename[filename] for filename in order if filename in by_filename]
    if not ordered:
        raise ValueError("emotion2vec分析結果と取得済み音声を対応付けできませんでした。")

    matrix_index = {filename: index for index, filename in enumerate(order)}
    standard_ranked = sorted(
        ordered,
        key=lambda item: (
            _centrality(matrix, matrix_index[_record_filename(item)]),
            float(item.get("duration", 0.0) or 0.0),
        ),
        reverse=True,
    )
    standard_records = _take_until_seconds(standard_ranked, 120.0)
    if not standard_records:
        raise ValueError("標準参照セットを自動選出できませんでした。")

    report("標準参照を作成中")
    char_name, sets = precompute_reference_sets(
        name,
        standard_records,
        page_url,
        target_seconds,
    )

    core_records = _select_core_records(standard_records)
    core_indices = [
        matrix_index[_record_filename(item)]
        for item in core_records
        if _record_filename(item) in matrix_index
    ]
    core_scores_all = [
        _mean_similarity(matrix, index, core_indices)
        for index in range(len(ordered))
    ]
    distribution_floor = _percentile(core_scores_all, 0.20)
    voice_floor = max(0.72, min(0.93, distribution_floor))

    generated_at = datetime.now().astimezone().isoformat(timespec="seconds")
    emotion_entries: dict[str, Any] = {}

    report("感情別参照を作成中")
    for emotion_key, default in EMOTION_DEFAULTS.items():
        scored: list[dict[str, Any]] = []
        for item in ordered:
            filename = _record_filename(item)
            index = matrix_index[filename]
            semantic_map = _semantic_scores(item)
            semantic = float(semantic_map.get(emotion_key, 0.0))
            other_semantic = max(
                (
                    float(value)
                    for key, value in semantic_map.items()
                    if key != emotion_key
                ),
                default=0.0,
            )
            core_score = _mean_similarity(matrix, index, core_indices)
            scored.append(
                {
                    "item": item,
                    "filename": filename,
                    "index": index,
                    "semantic": semantic,
                    "other_semantic": other_semantic,
                    "core_score": core_score,
                }
            )

        anchors = [
            value
            for value in sorted(
                scored,
                key=lambda value: (value["semantic"], value["core_score"]),
                reverse=True,
            )
            if (
                value["semantic"] > 0
                and value["semantic"] + 0.8 >= value["other_semantic"]
                and value["core_score"] >= voice_floor
            )
        ][:4]

        if not anchors:
            emotion_entries[emotion_key] = {
                **default,
                "status": "merged_into_standard",
                "use_standard_reference": True,
                "files_in_order": [],
                "total_duration_sec": 0.0,
                "notes": ["台詞内容から十分な感情候補を自動抽出できなかったため標準参照へフォールバック。"],
            }
            continue

        anchor_indices = [int(value["index"]) for value in anchors]
        ranked_emotion: list[tuple[float, dict[str, Any], float, float, float]] = []
        core_names = {_record_filename(item) for item in core_records}

        for value in scored:
            item = value["item"]
            if value["filename"] in core_names:
                continue
            anchor_similarity = max(
                float(matrix[value["index"]][anchor_index])
                for anchor_index in anchor_indices
            )
            semantic = float(value["semantic"])
            core_score = float(value["core_score"])
            if core_score < voice_floor:
                continue
            if float(value.get("other_semantic", 0.0)) > semantic + 0.8:
                continue
            if semantic <= 0 and anchor_similarity < AUTO_EMOTION_SIMILARITY_FLOOR:
                continue
            semantic_norm = min(1.0, semantic / 2.5)
            score = 0.50 * core_score + 0.35 * anchor_similarity + 0.15 * semantic_norm
            ranked_emotion.append(
                (score, item, core_score, anchor_similarity, semantic)
            )

        ranked_emotion.sort(key=lambda value: value[0], reverse=True)
        available_seconds = max(
            0.0,
            120.0 - sum(float(item.get("duration", 0.0) or 0.0) for item in core_records),
        )
        emotion_records = _take_until_seconds(
            [value[1] for value in ranked_emotion],
            available_seconds,
        )
        emotion_seconds = sum(float(item.get("duration", 0.0) or 0.0) for item in emotion_records)

        if len(emotion_records) < AUTO_MIN_EMOTION_FILES or emotion_seconds < AUTO_MIN_EMOTION_SECONDS:
            emotion_entries[emotion_key] = {
                **default,
                "status": "merged_into_standard",
                "use_standard_reference": True,
                "anchor_files": [value["filename"] for value in anchors],
                "files_in_order": [],
                "total_duration_sec": round(emotion_seconds, 3),
                "notes": ["声質を保てる感情候補が不足したため標準参照へフォールバック。"],
            }
            continue

        pool_records = list(core_records) + emotion_records
        files_in_order = [_record_filename(item) for item in pool_records]
        total_duration = sum(float(item.get("duration", 0.0) or 0.0) for item in pool_records)
        detail_by_name = {
            _record_filename(value[1]): {
                "selection_score": float(value[0]),
                "core_score": float(value[2]),
                "anchor_similarity": float(value[3]),
                "semantic_score": float(value[4]),
            }
            for value in ranked_emotion
        }
        core_score_by_name = {
            _record_filename(item): _mean_similarity(
                matrix,
                matrix_index[_record_filename(item)],
                core_indices,
            )
            for item in core_records
        }
        emotion_entries[emotion_key] = {
            **default,
            "status": "ready",
            "anchor_files": [value["filename"] for value in anchors],
            "files_in_order": files_in_order,
            "total_duration_sec": round(min(total_duration, 120.0), 3),
            "files": [
                {
                    "filename": _record_filename(item),
                    "role": "voice_core" if _record_filename(item) in core_names else "emotion",
                    "duration_sec": round(float(item.get("duration", 0.0) or 0.0), 3),
                    "transcription": str(item.get("transcript", "")).strip(),
                    "core_score": round(
                        float(
                            core_score_by_name.get(
                                _record_filename(item),
                                detail_by_name.get(_record_filename(item), {}).get("core_score", 0.0),
                            )
                        ),
                        6,
                    ),
                    "anchor_similarity": (
                        None
                        if _record_filename(item) in core_names
                        else round(
                            float(detail_by_name.get(_record_filename(item), {}).get("anchor_similarity", 0.0)),
                            6,
                        )
                    ),
                    "semantic_score": (
                        None
                        if _record_filename(item) in core_names
                        else round(
                            float(detail_by_name.get(_record_filename(item), {}).get("semantic_score", 0.0)),
                            3,
                        )
                    ),
                }
                for item in pool_records
            ],
        }

    plan = {
        "schema_version": 1,
        "status": "ready",
        "generated_at": generated_at,
        "producer": "auto-character-create",
        "character": char_name,
        "selection_policy": "voice_core_then_semantic_emotion_then_embedding_support",
        "source_generated_at": generated_at,
        "eligible": {
            "count": len(eligible),
            "total_duration_sec": round(
                sum(float(item.get("duration", 0.0) or 0.0) for item in eligible),
                3,
            ),
            "filters": {
                "minimum_duration_sec": 1.5,
                "maximum_duration_sec": 12.0,
                "combat_and_non_dialogue": True,
            },
        },
        "core": {
            "basis": "emotion2vec_centrality",
            "voice_floor": round(voice_floor, 6),
            "voice_floor_method": "20th_percentile_of_core_similarity_clamped_0.72_to_0.93",
            "common_anchor_duration_sec": round(
                sum(float(item.get("duration", 0.0) or 0.0) for item in core_records),
                3,
            ),
            "common_anchor_files": [_record_filename(item) for item in core_records],
            "standard_files_in_order": [_record_filename(item) for item in standard_records],
            "standard_total_duration_sec": round(
                sum(float(item.get("duration", 0.0) or 0.0) for item in standard_records),
                3,
            ),
        },
        "emotions": emotion_entries,
    }
    plan_path = _character_plan_path(char_name)
    write_json(plan_path, plan)

    ready_labels: list[str] = []
    fallback_labels: list[str] = []
    report("事前計算中")
    for emotion_key, entry in emotion_entries.items():
        if str(entry.get("status", "")) == "ready":
            try:
                resolve_emotion_reference(char_name, emotion_key)
                ready_labels.append(str(entry.get("label", emotion_key)))
            except Exception as exc:
                entry["status"] = "merged_into_standard"
                entry["use_standard_reference"] = True
                entry.setdefault("notes", []).append(
                    "感情参照の事前計算に失敗したため標準参照へフォールバック：" + str(exc)
                )
                fallback_labels.append(str(entry.get("label", emotion_key)))
        else:
            fallback_labels.append(str(entry.get("label", emotion_key)))

    write_json(plan_path, plan)
    report("完了")
    summary = {
        "eligible_count": len(eligible),
        "standard_count": len(standard_records),
        "standard_seconds": round(
            sum(float(item.get("duration", 0.0) or 0.0) for item in standard_records),
            3,
        ),
        "dedicated_emotions": ready_labels,
        "fallback_emotions": fallback_labels,
        "plan_path": str(plan_path),
    }
    return char_name, sets, summary


def select_emotion_mode(
    character: str,
    current_caption: str,
    emotion_key: str,
) -> tuple[str, str, str]:
    name = str(character or "").strip()
    key = str(emotion_key or "").strip()

    if key in {"", "standard"}:
        speaker = load_registry().get("speakers", {}).get(name, {})
        default_caption = str(speaker.get("default_caption", "")).strip() if isinstance(speaker, dict) else ""
        return "", default_caption, "標準：このキャラクターの通常参照を使います。"

    if not name:
        return "", str(current_caption or ""), "キャラクターを選択してください。"

    _plan, pool = _emotion_config(name, key)
    label = str(pool.get("label", key))
    caption = str(pool.get("caption", "")).strip()
    status = str(pool.get("status", "generic"))

    if status == "generic":
        return key, caption, f"{label}：専用参照は未作成です。標準120秒参照＋感情指示で生成します。"
    if status == "merged_into_standard":
        return key, caption, f"{label}：このキャラクターでは標準参照を使う個別設定です。"

    seconds = float(pool.get("total_duration_sec", 0.0) or 0.0)
    return key, caption, f"{label}：このキャラクター専用の感情参照 {seconds:.1f}秒を使います。"


def normalize_emotion_mix(mix: dict[str, Any] | None) -> dict[str, float]:
    raw = mix if isinstance(mix, dict) else {}
    values: dict[str, float] = {}
    for key in EMOTION_DEFAULTS:
        try:
            weight = float(raw.get(key, 0.0) or 0.0)
        except (TypeError, ValueError):
            weight = 0.0
        if weight > 0:
            values[key] = weight

    if len(values) > 3:
        raise ValueError("感情は最大3つまで選択できます。")
    total = sum(values.values())
    if total <= 0:
        return {}
    return {key: value * 100.0 / total for key, value in values.items()}


def emotion_mix_caption(character: str, mix: dict[str, Any] | None) -> str:
    normalized = normalize_emotion_mix(mix)
    captions: list[str] = []
    for key in normalized:
        _plan, pool = _emotion_config(character, key)
        caption = str(pool.get("caption", "")).strip()
        if caption and caption not in captions:
            captions.append(caption)
    return "。".join(captions)


def emotion_mix_status(character: str, mix: dict[str, Any] | None) -> str:
    normalized = normalize_emotion_mix(mix)
    if not normalized:
        return "標準：通常の参照秒数を使います。"

    parts: list[str] = []
    for key, weight in normalized.items():
        _plan, pool = _emotion_config(character, key)
        label = str(pool.get("label", key))
        parts.append(f"{label} {weight:.0f}%")
    return "選択中：" + " ＋ ".join(parts) + "。生成時はこの割合で参照音声を配分します。"


def resolve_emotion_mix_reference(
    character: str,
    mix: dict[str, Any] | None,
) -> tuple[Path, float, str, str]:
    normalized = normalize_emotion_mix(mix)
    if not normalized:
        path, actual = _standard_reference(str(character or "").strip())
        return path, actual, "", "標準"

    if len(normalized) == 1:
        key = next(iter(normalized))
        return resolve_emotion_reference(character, key)

    components: list[dict[str, Any]] = []
    for key, weight in normalized.items():
        path, actual, caption, label = resolve_emotion_reference(character, key)
        latent = torch.load(path, map_location="cpu", weights_only=True)
        latent = coerce_latent(latent)
        components.append(
            {
                "key": key,
                "weight": weight / 100.0,
                "path": path,
                "actual": actual,
                "caption": caption,
                "label": label,
                "latent": latent,
                "steps": int(latent.shape[1]),
                "mtime_ns": path.stat().st_mtime_ns,
            }
        )

    codec = get_codec()
    max_steps = max(1, int(round(120.0 * codec.sample_rate / codec.model.hop_length)))
    capacity_steps = min(
        int(component["steps"] / component["weight"])
        for component in components
        if component["weight"] > 0
    )
    target_steps = max(1, min(max_steps, capacity_steps))

    allocations: list[int] = []
    remaining = target_steps
    for index, component in enumerate(components):
        if index == len(components) - 1:
            steps = remaining
        else:
            steps = max(1, int(round(target_steps * component["weight"])))
            steps = min(steps, int(component["steps"]))
            remaining -= steps
        allocations.append(max(1, steps))

    if sum(allocations) > target_steps:
        overflow = sum(allocations) - target_steps
        for index in range(len(allocations) - 1, -1, -1):
            reducible = max(0, allocations[index] - 1)
            cut = min(reducible, overflow)
            allocations[index] -= cut
            overflow -= cut
            if overflow <= 0:
                break

    pieces = [
        component["latent"][:, :steps].contiguous()
        for component, steps in zip(components, allocations)
    ]
    combined = torch.cat(pieces, dim=1)

    folder = reference_set_dir(str(character or "").strip()) / "感情別" / "複合"
    folder.mkdir(parents=True, exist_ok=True)
    stem = "_".join(
        f"{component['key']}{int(round(normalized[component['key']]))}"
        for component in components
    )
    output = folder / f"{safe_name(stem, 'emotion_mix', 120)}.pt"
    manifest = output.with_suffix(".json")

    signature = [
        {
            "key": component["key"],
            "weight": round(normalized[component["key"]], 6),
            "path": str(component["path"]),
            "mtime_ns": int(component["mtime_ns"]),
        }
        for component in components
    ]
    if output.is_file() and manifest.is_file():
        old = read_json(manifest, {})
        if isinstance(old, dict) and old.get("signature") == signature:
            actual = float(old.get("actual_duration_sec", 0.0) or 0.0)
            if actual > 0:
                return (
                    output,
                    actual,
                    emotion_mix_caption(character, normalized),
                    "＋".join(
                        f"{component['label']}{normalized[component['key']]:.0f}%"
                        for component in components
                    ),
                )

    torch.save(combined, output)
    actual = combined.shape[1] * int(codec.model.hop_length) / int(codec.sample_rate)
    caption = emotion_mix_caption(character, normalized)
    label = "＋".join(
        f"{component['label']}{normalized[component['key']]:.0f}%"
        for component in components
    )
    write_json(
        manifest,
        {
            "character": str(character or "").strip(),
            "kind": "emotion_mix",
            "weights": {key: round(value, 6) for key, value in normalized.items()},
            "signature": signature,
            "allocation_steps": allocations,
            "actual_duration_sec": round(actual, 3),
            "caption": caption,
            "label": label,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "official_registry_updated": False,
        },
    )
    return output, actual, caption, label


def _resolve_audio_files(character: str, filenames: list[str]) -> list[Path]:
    metadata = load_audio_metadata(character)
    records = metadata.get("files", []) if isinstance(metadata, dict) else []
    by_name: dict[str, Path] = {}

    for item in records if isinstance(records, list) else []:
        if not isinstance(item, dict):
            continue
        raw = str(item.get("path", "")).strip()
        filename = Path(raw).name if raw else str(item.get("filename", "")).strip()
        if filename and raw:
            path = Path(raw)
            if path.is_file():
                by_name[filename] = path

    base = downloaded_audio_dir(character)
    resolved: list[Path] = []
    missing: list[str] = []
    for filename in filenames:
        name = str(filename)
        path = by_name.get(name)
        if path is None:
            fallback = base / name
            if fallback.is_file():
                path = fallback
        if path is None:
            missing.append(name)
        else:
            resolved.append(path)

    if missing:
        raise FileNotFoundError("感情別参照の音声が見つかりません：" + "、".join(missing))
    return resolved


def resolve_emotion_reference(
    character: str,
    emotion_key: str,
    max_seconds: float = 120.0,
) -> tuple[Path, float, str, str]:
    name = str(character or "").strip()
    if not name:
        raise ValueError("キャラクターを選択してください。")

    plan, pool = _emotion_config(name, emotion_key)
    key = str(emotion_key).strip()
    caption = str(pool.get("caption", "")).strip()
    label = str(pool.get("label", key))

    limit_seconds = max(1.0, min(120.0, float(max_seconds or 120.0)))
    requested_standard_seconds = 30 if limit_seconds <= 30.0 else 120

    if bool(pool.get("use_standard_reference", False)):
        path, actual = _standard_reference(name, requested_standard_seconds)
        return path, actual, caption, label

    filenames = [str(value) for value in pool.get("files_in_order", [])]
    if not filenames:
        path, actual = _standard_reference(name, requested_standard_seconds)
        return path, actual, caption, label

    folder = reference_set_dir(name) / "感情別"
    folder.mkdir(parents=True, exist_ok=True)
    suffix = "" if limit_seconds >= 119.999 else f"_{int(round(limit_seconds))}秒"
    output = folder / f"{safe_name(key, 'emotion')}{suffix}.pt"
    manifest = output.with_suffix(".json")

    expected_source = str(plan.get("source_generated_at", ""))
    if output.is_file() and manifest.is_file():
        old = read_json(manifest, {})
        stored_limit = float(old.get("max_ref_seconds", 120.0) or 120.0) if isinstance(old, dict) else 120.0
        if (
            isinstance(old, dict)
            and old.get("files_in_order") == filenames
            and str(old.get("source_generated_at", "")) == expected_source
            and abs(stored_limit - limit_seconds) < 0.001
        ):
            actual = float(old.get("actual_duration_sec", 0.0) or 0.0)
            if actual > 0:
                return output, actual, caption, label

    audio_files = _resolve_audio_files(name, filenames)
    codec = get_codec()
    latent_dir = precomputed_dir(name)
    latent_dir.mkdir(parents=True, exist_ok=True)

    pieces: list[torch.Tensor] = []
    for audio_path in audio_files:
        latent_path = latent_dir / f"{audio_path.stem}.pt"
        pieces.append(coerce_latent(latent_for_audio(codec, audio_path, latent_path)))

    if not pieces:
        raise ValueError("感情別参照を作成できませんでした。")

    combined = torch.cat(pieces, dim=1)
    max_steps = max(1, int(round(limit_seconds * codec.sample_rate / codec.model.hop_length)))
    combined = combined[:, :max_steps].contiguous()
    torch.save(combined, output)

    actual = combined.shape[1] * int(codec.model.hop_length) / int(codec.sample_rate)
    write_json(
        manifest,
        {
            "character": name,
            "emotion_key": key,
            "label": label,
            "caption": caption,
            "files_in_order": filenames,
            "source_generated_at": expected_source,
            "actual_duration_sec": round(actual, 3),
            "max_ref_seconds": round(limit_seconds, 3),
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "official_registry_updated": False,
        },
    )
    return output, actual, caption, label

