_INVALID_NAME = re.compile(r'[<>:"/\\|?*\x00-\x1f]')


def safe_name(value: str, fallback: str = "名称未設定", max_length: int = 80) -> str:
    text = unicodedata.normalize("NFKC", str(value or "")).strip()
    text = _INVALID_NAME.sub("_", text)
    text = re.sub(r"\s+", " ", text).strip(" .")
    if not text:
        text = fallback
    return text[:max_length].rstrip(" .") or fallback


def character_dir(character: str) -> Path:
