param(
    [switch]$NoBrowser
)

$ErrorActionPreference = 'Stop'

$url = 'http://127.0.0.1:7862/'
$toolDir = $PSScriptRoot
$startupLogPath = Join-Path $toolDir '_last_startup.log'
$startupStdoutPath = Join-Path $toolDir '_last_startup_stdout.log'
$pythonPath = '/home/rensei/Irodori-TTS/.venv/bin/python'

function Test-LocalApp {
    try {
        $response = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 2
        return ($response.StatusCode -eq 200)
    } catch {
        return $false
    }
}

function Wait-LocalApp {
    for ($attempt = 0; $attempt -lt 80; $attempt++) {
        if (Test-LocalApp) {
            return $true
        }
        Start-Sleep -Milliseconds 500
    }
    return $false
}

function Convert-AsciiWindowsPathToWsl {
    param([string]$WindowsPath)

    if ($WindowsPath -notmatch '^([A-Za-z]):\\(.*)$') {
        throw "Unsupported junction path: $WindowsPath"
    }
    $drive = $Matches[1].ToLowerInvariant()
    $relative = $Matches[2].Replace('\', '/')
    if ($relative -match '[^\x00-\x7F]') {
        throw 'Fallback junction path must be ASCII.'
    }
    return "/mnt/$drive/$relative"
}

function Get-AsciiJunctionPath {
    $driveRoot = [System.IO.Path]::GetPathRoot($toolDir)
    if (-not $driveRoot -or $driveRoot -notmatch '^[A-Za-z]:\\$') {
        throw 'The tool must be on a Windows drive for the ASCII junction fallback.'
    }

    $junctionPath = Join-Path $driveRoot '_fandom_voice_tool_link'
    if (Test-Path -LiteralPath $junctionPath) {
        $item = Get-Item -LiteralPath $junctionPath -Force
        if ($item.LinkType -ne 'Junction') {
            throw "Fallback path already exists and is not a junction: $junctionPath"
        }

        $junctionTarget = @($item.Target)[0]
        if (-not $junctionTarget) {
            throw "Fallback junction target could not be read. Startup stopped without changing it."
        }

        $expectedTarget = [System.IO.Path]::GetFullPath($toolDir).TrimEnd('\')
        $actualTarget = [System.IO.Path]::GetFullPath([string]$junctionTarget).TrimEnd('\')
        if (-not [string]::Equals($expectedTarget, $actualTarget, [System.StringComparison]::OrdinalIgnoreCase)) {
            throw "Fallback junction points to a different folder. Startup stopped without changing it."
        }

        return $junctionPath
    }

    New-Item -ItemType Junction -Path $junctionPath -Target $toolDir | Out-Null
    return $junctionPath
}

function Test-AsciiJunctionInWsl {
    param([string]$WslPath)

    $command = "test -d '$WslPath' && printf FANDOM_TOOL_OK"
    $probe = & wsl.exe -d Ubuntu -- bash -lc $command 2>$null
    return (($LASTEXITCODE -eq 0) -and (($probe -join '') -eq 'FANDOM_TOOL_OK'))
}

function Start-AppWithAsciiJunction {
    param([string]$WslPath)

    $argumentString = "-d Ubuntu --cd $WslPath -- $pythonPath app.py"
    Start-Process -FilePath 'wsl.exe' -ArgumentList $argumentString -WindowStyle Hidden -RedirectStandardOutput $startupStdoutPath -RedirectStandardError $startupLogPath | Out-Null
}

function Write-StartupFailureLog {
    $parts = New-Object 'System.Collections.Generic.List[string]'
    if (Test-Path -LiteralPath $startupLogPath) {
        $text = Get-Content -LiteralPath $startupLogPath -Raw -ErrorAction SilentlyContinue
        if ($text) {
            $parts.Add($text.TrimEnd()) | Out-Null
        }
    }
    if (Test-Path -LiteralPath $startupStdoutPath) {
        $text = Get-Content -LiteralPath $startupStdoutPath -Raw -ErrorAction SilentlyContinue
        if ($text) {
            $parts.Add($text.TrimEnd()) | Out-Null
        }
    }
    if ($parts.Count -gt 0) {
        Set-Content -LiteralPath $startupLogPath -Value ($parts -join [Environment]::NewLine) -Encoding UTF8
    }
}

try {
    if (Test-LocalApp) {
        if (-not $NoBrowser) {
            Start-Process $url
        }
        exit 0
    }

    $appPath = Join-Path $toolDir 'app.py'
    if (-not (Test-Path -LiteralPath $appPath)) {
        throw "app.py was not found: $appPath"
    }

    Remove-Item -LiteralPath $startupLogPath -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $startupStdoutPath -Force -ErrorAction SilentlyContinue

    $junctionPath = Get-AsciiJunctionPath
    $junctionWslPath = Convert-AsciiWindowsPathToWsl $junctionPath
    if (-not (Test-AsciiJunctionInWsl $junctionWslPath)) {
        throw 'ASCII junction startup path could not be opened from WSL.'
    }
    Start-AppWithAsciiJunction $junctionWslPath

    if (-not (Wait-LocalApp)) {
        Write-StartupFailureLog
        throw 'Local startup failed. Check _last_startup.log.'
    }

    if (-not $NoBrowser) {
        Start-Process $url
    }
    exit 0
} catch {
    Write-Host $_.Exception.Message
    exit 1
}

