from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any

from paths import (
    DICTIONARY_PATH,
    GAMES_PATH,
    HISTORY_PATH,
    REGISTRY_PATH,
    character_metadata_path,
)


def read_json(path: Path, default: Any) -> Any:
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def write_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    temp.replace(path)


def load_registry() -> dict[str, Any]:
    data = read_json(REGISTRY_PATH, {"speakers": {}})
    if not isinstance(data, dict) or not isinstance(data.get("speakers"), dict):
        return {"speakers": {}}
    return data


def save_registry(data: dict[str, Any]) -> None:
    write_json(REGISTRY_PATH, data)


def load_games() -> dict[str, str]:
    data = read_json(GAMES_PATH, {"games": {}})
    games = data.get("games", {}) if isinstance(data, dict) else {}
    if not isinstance(games, dict):
        return {}
    return {str(key): str(value) for key, value in games.items() if str(key).strip() and str(value).strip()}


def save_games(games: dict[str, str]) -> None:
    write_json(GAMES_PATH, {"games": games})


def load_dictionary_data() -> dict[str, Any]:
    data = read_json(DICTIONARY_PATH, {"common": {}})
    return data if isinstance(data, dict) else {"common": {}}


def save_dictionary_data(data: dict[str, Any]) -> None:
    write_json(DICTIONARY_PATH, data)


def append_history(entry: dict[str, Any]) -> None:
    HISTORY_PATH.parent.mkdir(parents=True, exist_ok=True)
    value = dict(entry)
    value.setdefault("id", datetime.now().strftime("%Y%m%d%H%M%S%f"))
    with HISTORY_PATH.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(value, ensure_ascii=False) + "\n")


def load_history(limit: int = 300) -> list[dict[str, Any]]:
    if not HISTORY_PATH.exists():
        return []
    items: list[dict[str, Any]] = []
    for line in HISTORY_PATH.read_text(encoding="utf-8").splitlines():
        try:
            value = json.loads(line)
            if isinstance(value, dict):
                items.append(value)
        except Exception:
            continue
    return list(reversed(items[-limit:]))


def load_audio_metadata(character: str) -> dict[str, Any]:
    data = read_json(character_metadata_path(character), {})
    return data if isinstance(data, dict) else {}


def save_audio_metadata(character: str, data: dict[str, Any]) -> None:
    write_json(character_metadata_path(character), data)

