from typing import Any
from urllib.parse import urlparse

os.environ.setdefault("HSA_ENABLE_DXG_DETECTION", "1")

import gradio as gr
import numpy as np
import soundfile as sf
import torch

from audio_join import build_join_audio, join_safe_stem, write_join_wav
from game_catalog import all_game_wikis
from emotion_reference_service import resolve_emotion_mix_reference, resolve_emotion_reference
from paths import IRODORI_ROOT, OUTPUT_ROOT, TEMP_GENERATION_ROOT, generated_character_dir, safe_name
from storage import append_history, load_dictionary_data, load_history, load_registry

if str(IRODORI_ROOT) not in sys.path:
    sys.path.insert(0, str(IRODORI_ROOT))

from irodori_tts.inference_runtime import (
    InferenceRuntime,
    RuntimeKey,
    SamplingRequest,
    download_hf_checkpoint,
    save_wav,
)


TARGET_SECONDS = (30, 60, 90, 120)
COMPARE_SEED = 20260921
EMOJI_TAIL_COMPARE_SEED = 20260924

_runtime: InferenceRuntime | None = None
_model_path: str | None = None
_load_lock = threading.RLock()
_generation_lock = threading.Lock()
_generation_queue_lock = threading.RLock()
_generation_jobs: list[dict[str, Any]] = []
_generation_results: list[dict[str, Any]] = []
_generation_worker_thread: threading.Thread | None = None
_generation_job_counter = 0
_generation_result_counter = 0
_long_generation_groups: dict[str, dict[str, Any]] = {}
_long_generation_group_counter = 0

EMOTION_KEYS = ("cheerful", "angry", "surprised", "worried", "gentle")
EMOTION_EMOJI_NORMAL = {
    "cheerful": "😆",
    "angry": "😠",
    "surprised": "😲",
    "worried": "😟",
    "gentle": "🫶",
}
EMOTION_EMOJI_STRONG = {
    "cheerful": "😆😆",
    "angry": "😠💥",
    "surprised": "😱",
    "worried": "😰",
    "gentle": "🫶🫶",
}


def _apply_pronunciations(text: str, character: str) -> str:
    data = load_dictionary_data()
    common = data.get("common", {}) if isinstance(data, dict) else {}
    values = {str(key): str(value) for key, value in common.items()} if isinstance(common, dict) else {}

    speaker = load_registry().get("speakers", {}).get(str(character or ""), {})
    character_values = speaker.get("pronunciation", {}) if isinstance(speaker, dict) else {}
    if isinstance(character_values, dict):
        values.update({str(key): str(value) for key, value in character_values.items()})

    processed = str(text)
    for word in sorted(values, key=len, reverse=True):
        if word:
            processed = processed.replace(word, values[word])
    return processed


def emotion_emoji_suffix(
    emotion_mix: dict[str, Any] | None,
    emotion_key: str = "",
    strength: str = "通常",
) -> str:
    selected: list[str] = []
    mix = emotion_mix if isinstance(emotion_mix, dict) else {}
    for key in EMOTION_KEYS:
        try:
            active = float(mix.get(key, 0.0) or 0.0) > 0
        except (TypeError, ValueError):
            active = False
        if active:
            selected.append(key)

    key = str(emotion_key or "").strip()
    if not selected and key in EMOTION_KEYS:
        selected = [key]

    mapping = EMOTION_EMOJI_STRONG if str(strength or "") == "強い" else EMOTION_EMOJI_NORMAL
    return "".join(mapping.get(key, "") for key in selected)


def build_internal_generation_text(
    text: str,
    character: str,
    emotion_mix: dict[str, Any] | None = None,
    emotion_key: str = "",
    emoji_enabled: bool = False,
    emoji_strength: str = "通常",
) -> str:
    processed = _apply_pronunciations(str(text).strip(), character)
    if not emoji_enabled:
        return processed
    suffix = emotion_emoji_suffix(emotion_mix, emotion_key, emoji_strength)
    if not suffix:
        return processed
    return f"{processed}{suffix}"


def normalize_generation_controls(
    cfg_scale_caption: float = 4.0,
    cfg_scale_speaker: float = 5.0,
    speaker_kv_scale: float | None = None,
) -> tuple[float, float, float | None]:
    caption_scale = max(0.0, min(10.0, float(cfg_scale_caption)))
    speaker_scale = max(0.0, min(10.0, float(cfg_scale_speaker)))
    kv_scale = None
    if speaker_kv_scale is not None:
        kv_scale = max(0.1, min(3.0, float(speaker_kv_scale)))
    return caption_scale, speaker_scale, kv_scale


def history_rows() -> list[list[Any]]:
    return [[
        item.get("datetime", ""),
        item.get("character", ""),
        item.get("text", ""),
        item.get("caption", ""),
        item.get("ref_seconds", ""),
        item.get("seed", ""),
        Path(str(item.get("output", ""))).name,
    ] for item in load_history()]


def history_dropdown() -> Any:
    choices = [
        (
            f"{item.get('datetime', '')}｜{item.get('character', '')}｜{str(item.get('text', ''))[:28]}",
            item.get("id", ""),
        )
        for item in load_history()
    ]
    return gr.Dropdown(
        choices=choices,
        value=choices[0][1] if choices else None,
        label="再利用する履歴",
    )


def get_runtime() -> InferenceRuntime:
    global _runtime, _model_path
    with _load_lock:
        if _runtime is None:
            if not torch.cuda.is_available():
                raise RuntimeError("AMD GPUを認識できません。Irodori-TTSの既存環境を確認してください。")
            _model_path = download_hf_checkpoint("Aratako/Irodori-TTS-v4.1-Small")
            _runtime = InferenceRuntime.from_key(RuntimeKey(
                checkpoint=str(_model_path),
                model_device="cuda",
                model_precision="fp32",
                codec_device="cpu",
                codec_precision="fp32",
                codec_deterministic_encode=False,
                codec_deterministic_decode=False,
                compile_model=False,
                compile_dynamic=False,
            ))
        return _runtime


def speaker_game_name(character: str) -> str:
    speaker = load_registry().get("speakers", {}).get(str(character or ""), {})
    if isinstance(speaker, dict):
        manual_game_name = str(speaker.get("game_name", "")).strip()
        if manual_game_name:
            return manual_game_name

    source_page = str(speaker.get("source_page", "")) if isinstance(speaker, dict) else ""
    source_host = (urlparse(source_page).hostname or "").casefold()
    if not source_host:
        return ""

    for game_name, wiki_url in all_game_wikis().items():
        if (urlparse(str(wiki_url)).hostname or "").casefold() == source_host:
            return str(game_name)
    return ""


def output_name(character: str, text: str, suffix: str = "") -> Path:
    summary = safe_name(str(text).strip().replace("。", "").replace("、", ""), "音声", 18)
    stamp = datetime.now().strftime("%Y%m%d_%H%M")
    extra = f"_{suffix}" if suffix else ""
    base = safe_name(f"{character}_{summary}_{stamp}{extra}", "生成音声", 120)
    game_name = speaker_game_name(character)
    output_dir = OUTPUT_ROOT
    if game_name and str(character or "").strip():
        output_dir = generated_character_dir(game_name, character)
    output_dir.mkdir(parents=True, exist_ok=True)

    candidate = output_dir / f"{base}.wav"
    index = 2
    while candidate.exists():
        candidate = output_dir / f"{base}_{index}.wav"
        index += 1
    return candidate

def cleanup_temporary_generation_files() -> None:
    TEMP_GENERATION_ROOT.mkdir(parents=True, exist_ok=True)
    for child in list(TEMP_GENERATION_ROOT.iterdir()):
        try:
            if child.is_dir():
                shutil.rmtree(child)
            else:
                child.unlink()
        except FileNotFoundError:
            pass


def _temp_output_name(character: str, text: str, suffix: str = "") -> Path:
    summary = safe_name(str(text).strip().replace("。", "").replace("、", ""), "音声", 18)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    extra = f"_{suffix}" if suffix else ""
    base = safe_name(f"{character}_{summary}_{stamp}{extra}", "一時音声", 120)
    output_dir = TEMP_GENERATION_ROOT / safe_name(character, "キャラクター")
    output_dir.mkdir(parents=True, exist_ok=True)
    candidate = output_dir / f"{base}.wav"
    index = 2
    while candidate.exists():
        candidate = output_dir / f"{base}_{index}.wav"
        index += 1
    return candidate


def _is_temp_generation_path(value: str | Path) -> bool:
    try:
        path = Path(value).resolve()
        root = TEMP_GENERATION_ROOT.resolve()
        return path == root or root in path.parents
    except Exception:
        return False


def _temp_result_sidecar_path(value: str | Path) -> Path:
    return Path(value).with_suffix(".result.json")


def _write_temp_result_sidecar(
    output: str | Path,
    metadata: dict[str, Any],
    suffix: str,
) -> None:
    if not _is_temp_generation_path(output):
        return
    path = Path(output)
    if not path.is_file():
        return
    sidecar = _temp_result_sidecar_path(path)
    payload = {
        "metadata": dict(metadata),
        "suffix": str(suffix or ""),
    }
    try:
        sidecar.write_text(
            json.dumps(payload, ensure_ascii=False, indent=2, default=str),
            encoding="utf-8",
        )
    except OSError:
        pass


def _delete_temp_result_sidecar(value: str | Path) -> None:
    if not _is_temp_generation_path(value):
        return
    try:
        _temp_result_sidecar_path(value).unlink()
    except FileNotFoundError:
        pass


def _delete_temp_generation_path(value: str | Path) -> None:
    if not _is_temp_generation_path(value):
        return
    try:
        path = Path(value)
        if path.is_file():
            path.unlink()
    except FileNotFoundError:
        pass
    _delete_temp_result_sidecar(value)


def generation_results_snapshot() -> list[dict[str, Any]]:
    with _generation_queue_lock:
        return [dict(item) for item in _generation_results]


def generation_results_render_token() -> str:
    items = generation_results_snapshot()
    payload = [
        {
            "id": int(item.get("id", 0) or 0),
            "status": str(item.get("status", "")),
            "saved": bool(item.get("saved", False)),
            "recovered": bool(item.get("recovered", False)),
            "output": str(item.get("output", "")),
        }
        for item in items
    ]
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def _register_generation_result(
    output: str,
    metadata: dict[str, Any],
    suffix: str,
) -> int:
    global _generation_result_counter
    with _generation_queue_lock:
        _generation_result_counter += 1
        result_id = _generation_result_counter
        _generation_results.append({
            "id": result_id,
            "status": "未保存",
            "saved": False,
            "recovered": False,
            "output": str(output),
            "filename": Path(str(output)).name,
            "character": str(metadata.get("character", "")),
            "text": str(metadata.get("text", "")),
            "seed": int(metadata.get("seed", 0) or 0),
            "suffix": str(suffix or ""),
            "metadata": dict(metadata),
        })
    _write_temp_result_sidecar(output, metadata, suffix)
    return result_id


def recover_temporary_generation_results() -> list[dict[str, Any]]:
    global _generation_result_counter

    TEMP_GENERATION_ROOT.mkdir(parents=True, exist_ok=True)
    with _generation_queue_lock:
        existing = {
            str(Path(str(item.get("output", ""))).resolve())
            for item in _generation_results
            if str(item.get("output", "")).strip()
        }

    for wav_path in sorted(TEMP_GENERATION_ROOT.rglob("*.wav")):
        try:
            relative = wav_path.relative_to(TEMP_GENERATION_ROOT)
        except ValueError:
            continue
        if not relative.parts or any(part.startswith("_") for part in relative.parts[:-1]):
            continue

        resolved = str(wav_path.resolve())
        if resolved in existing:
            continue

        metadata: dict[str, Any] = {}
        suffix = "復元"
        sidecar = _temp_result_sidecar_path(wav_path)
        if sidecar.is_file():
            try:
                payload = json.loads(sidecar.read_text(encoding="utf-8"))
                if isinstance(payload, dict):
                    stored_metadata = payload.get("metadata", {})
                    if isinstance(stored_metadata, dict):
                        metadata = dict(stored_metadata)
                    suffix = str(payload.get("suffix", suffix) or suffix)
            except (OSError, json.JSONDecodeError):
                pass

        character = str(metadata.get("character", "")).strip() or wav_path.parent.name
        text = str(metadata.get("text", "")).strip() or wav_path.stem
        metadata["character"] = character
        metadata["text"] = text
        metadata["temp_output"] = str(wav_path)
        metadata.setdefault("seed", 0)

        result_id = _register_generation_result(str(wav_path), metadata, suffix)
        with _generation_queue_lock:
            item = next(
                (
                    entry
                    for entry in _generation_results
                    if int(entry.get("id", -1)) == int(result_id)
                ),
                None,
            )
            if item is not None:
                item["recovered"] = True
                item["status"] = "未保存（復元）"
        existing.add(resolved)

    return generation_results_snapshot()


def save_generation_result(result_id: int) -> tuple[list[dict[str, Any]], list[list[Any]], Any, str]:
    with _generation_queue_lock:
        item = next(
            (entry for entry in _generation_results if int(entry.get("id", -1)) == int(result_id)),
            None,
        )
        if item is None:
            return generation_results_snapshot(), history_rows(), history_dropdown(), "対象の生成結果が見つかりません。"
        if bool(item.get("saved")):
            return generation_results_snapshot(), history_rows(), history_dropdown(), "この音声は保存済みです。"
        source = str(item.get("output", ""))
        metadata = dict(item.get("metadata", {}))
        suffix = str(item.get("suffix", ""))

    source_path = Path(source)
    if not source_path.is_file() or not _is_temp_generation_path(source_path):
        return generation_results_snapshot(), history_rows(), history_dropdown(), "未保存音声が見つかりません。"

    target = output_name(
        str(metadata.get("character", "")),
        str(metadata.get("text", "")),
        suffix,
    )
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(source_path), str(target))
    _delete_temp_result_sidecar(source_path)

    history_entry = dict(metadata)
    history_entry["output"] = str(target)
    history_entry.pop("temp_output", None)
    append_history(history_entry)

    with _generation_queue_lock:
        item = next(
            (entry for entry in _generation_results if int(entry.get("id", -1)) == int(result_id)),
            None,
        )
        if item is not None:
            item["saved"] = True
            item["status"] = "保存済み"
            item["output"] = str(target)
            item["filename"] = target.name
            item["metadata"] = history_entry

    return (
        generation_results_snapshot(),
        history_rows(),
        history_dropdown(),
        f"保存しました：{target}",
    )


def discard_generation_result(result_id: int) -> tuple[list[dict[str, Any]], str]:
    with _generation_queue_lock:
        item = next(
            (entry for entry in _generation_results if int(entry.get("id", -1)) == int(result_id)),
            None,
        )
        if item is None:
            return generation_results_snapshot(), "対象の生成結果が見つかりません。"
        if bool(item.get("saved")):
            return generation_results_snapshot(), "保存済み音声は削除しません。"
        source = str(item.get("output", ""))

    _delete_temp_generation_path(source)

    with _generation_queue_lock:
        _generation_results[:] = [
            entry
            for entry in _generation_results
            if int(entry.get("id", -1)) != int(result_id)
        ]

    return generation_results_snapshot(), "未保存音声を破棄しました。"


def stage_generation_result_for_join(result_id: int) -> tuple[str | None, str]:
    with _generation_queue_lock:
        item = next(
            (entry for entry in _generation_results if int(entry.get("id", -1)) == int(result_id)),
            None,
        )
        if item is None:
            return None, "対象の生成結果が見つかりません。"
        source = Path(str(item.get("output", "")))

    if not source.is_file():
        return None, "音声ファイルが見つかりません。"

    staging_dir = TEMP_GENERATION_ROOT / "_join_staging"
    staging_dir.mkdir(parents=True, exist_ok=True)
    target = staging_dir / f"{datetime.now().strftime('%Y%m%d_%H%M%S_%f')}_{safe_name(source.name, 'audio.wav', 120)}"
    shutil.copy2(source, target)
    return str(target), "音声結合へ追加しました。"


def speaker_set(character: str, seconds: int) -> Path:
    speaker = load_registry().get("speakers", {}).get(character)
    if not speaker:
        raise ValueError("キャラクターが未登録です。先に参照セットを作成してください。")

    info = speaker.get("sets", {}).get(str(seconds))
    if not info:
        raise ValueError(f"{seconds}秒の参照セットがありません。")

    path = Path(info["path"])
    if not path.exists():
        raise FileNotFoundError(f"参照セットが見つかりません：{path}")
    return path


def synthesize_one(
    runtime: InferenceRuntime,
    character: str,
    text: str,
    caption: str,
    ref_seconds: int,
    seed: int,
    suffix: str,
    emotion_key: str = "",
    emotion_mix: dict[str, Any] | None = None,
    cfg_scale_caption: float = 4.0,
    emoji_enabled: bool = False,
    emoji_strength: str = "通常",
    cfg_scale_speaker: float = 5.0,
    speaker_kv_scale: float | None = None,
    reference_max_seconds: float | None = None,
    force_standard_reference: bool = False,
) -> tuple[str, Any, dict[str, Any]]:
    effective_caption = str(caption).strip()
    effective_seconds = float(ref_seconds)
    reference_mode = "standard"
    latent_path = speaker_set(character, ref_seconds)
    mix = dict(emotion_mix or {})

    if force_standard_reference:
        latent_path = speaker_set(character, 120)
        effective_seconds = 120.0
        reference_mode = "standard:120"
    elif isinstance(mix, dict) and any(float(value or 0) > 0 for value in mix.values()):
        active_keys = [
            key for key, value in mix.items()
            if float(value or 0) > 0
        ]
        if reference_max_seconds is not None and len(active_keys) == 1:
            latent_path, effective_seconds, default_emotion_caption, emotion_label = resolve_emotion_reference(
                character,
                active_keys[0],
                max_seconds=float(reference_max_seconds),
            )
        else:
            latent_path, effective_seconds, default_emotion_caption, emotion_label = resolve_emotion_mix_reference(
                character,
                mix,
            )
        if not effective_caption:
            effective_caption = default_emotion_caption
        reference_mode = f"emotion_mix:{emotion_label}"
        if reference_max_seconds is not None and len(active_keys) == 1:
            reference_mode += f":{int(round(float(reference_max_seconds)))}s"
    elif str(emotion_key or "").strip():
        latent_path, effective_seconds, default_emotion_caption, emotion_label = resolve_emotion_reference(
            character,
            str(emotion_key).strip(),
            max_seconds=float(reference_max_seconds or 120.0),
        )
        if not effective_caption:
            effective_caption = default_emotion_caption
        reference_mode = f"emotion:{emotion_label}"
        if reference_max_seconds is not None:
            reference_mode += f":{int(round(float(reference_max_seconds)))}s"

    processed_text = build_internal_generation_text(
        text,
        character,
        mix,
        emotion_key,
        bool(emoji_enabled),
        emoji_strength,
    )
    caption_scale, speaker_scale, kv_scale = normalize_generation_controls(
        cfg_scale_caption,
        cfg_scale_speaker,
        speaker_kv_scale,
    )
    synthesis_started = perf_counter()
    result = runtime.synthesize(SamplingRequest(
        text=processed_text,
        caption=effective_caption or None,
        ref_latent=str(latent_path),
        no_ref=False,
        ref_normalize_db=None,
        ref_ensure_max=False,
        max_ref_seconds=effective_seconds,
        num_steps=None,
        seed=int(seed),
        decode_mode="sequential",
        cfg_scale_caption=caption_scale,
        cfg_scale_speaker=speaker_scale,
        cfg_guidance_mode="independent",
        speaker_kv_scale=kv_scale,
        trim_tail=True,
    ))
    synthesis_seconds = perf_counter() - synthesis_started

    output = _temp_output_name(character, text, suffix)
    save_wav(output, result.audio, result.sample_rate)
    metadata = {
        "id": datetime.now().strftime("%Y%m%d%H%M%S%f"),
        "datetime": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "character": character,
        "text": str(text).strip(),
        "processed_text": processed_text,
        "caption": effective_caption,
        "ref_seconds": round(effective_seconds, 3),
        "emotion_key": str(emotion_key or "").strip(),
        "emotion_mix": mix,
        "reference_mode": reference_mode,
        "cfg_scale_caption": caption_scale,
        "cfg_scale_speaker": speaker_scale,
        "speaker_kv_scale": kv_scale,
        "emoji_enabled": bool(emoji_enabled),
        "emoji_strength": str(emoji_strength or "通常"),
        "seed": int(result.used_seed),
        "synthesis_seconds": round(float(synthesis_seconds), 3),
        "temp_output": str(output),
    }
    return str(output), result, metadata


def generate_candidates(
    character: str,
    text: str,
    caption: str,
    ref_seconds: int,
    count: int,
    cfg_scale_caption: float = 4.0,
    emoji_enabled: bool = False,
    emoji_strength: str = "通常",
    cfg_scale_speaker: float = 5.0,
    speaker_kv_scale: float | None = None,
) -> tuple[Any, ...]:
    paths: list[str | None] = []
    try:
        if not str(character or "").strip():
            raise ValueError("キャラクターを選択してください。")
        if not str(text or "").strip():
            raise ValueError("文章を入力してください。")

        seconds = int(ref_seconds)
        number = max(1, min(4, int(count)))
        messages: list[str] = []
        with _generation_lock:
            runtime = get_runtime()
            for index in range(1, number + 1):
                seed = random.SystemRandom().randrange(1, 2_147_483_647)
                path, result, _metadata = synthesize_one(
                    runtime,
                    character,
                    text,
                    caption,
                    seconds,
                    seed,
                    f"参照{seconds}秒_候補{index}",
                    "",
                    None,
                    cfg_scale_caption,
                    emoji_enabled,
                    emoji_strength,
                    cfg_scale_speaker,
                    speaker_kv_scale,
                )
                paths.append(path)
                messages.append(f"候補{index}：乱数 {result.used_seed}")

        while len(paths) < 4:
            paths.append(None)
        return (
            *paths[:4],
            f"{number}本を生成しました。" + "／".join(messages),
            history_rows(),
            history_dropdown(),
        )
    except Exception as exc:
        while len(paths) < 4:
            paths.append(None)
        return (
            *paths[:4],
            f"エラー：{exc}",
            history_rows(),
            history_dropdown(),
        )


def split_long_text(value: str, max_chars: int = 120) -> list[str]:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return []

    limit = max(20, min(500, int(max_chars)))
    parts = [
        re.sub(r"[ \t]+", " ", part).strip()
        for part in re.split(r"(?<=[。！？!?])|\n+", text)
        if str(part).strip()
    ]
    chunks: list[str] = []
    buffer = ""

    def flush_buffer() -> None:
        nonlocal buffer
        if buffer.strip():
            chunks.append(buffer.strip())
        buffer = ""

    for part in parts:
        while len(part) > limit:
            flush_buffer()
            window = part[:limit + 1]
            cut = max(
                window.rfind("、"),
                window.rfind("，"),
                window.rfind(","),
                window.rfind("；"),
                window.rfind(";"),
                window.rfind(" "),
            )
            if cut < max(10, limit // 2):
                cut = limit
            else:
                cut += 1
            chunks.append(part[:cut].strip())
            part = part[cut:].strip()

        if not part:
            continue

        candidate = part if not buffer else buffer + part
        if len(candidate) <= limit:
            buffer = candidate
        else:
            flush_buffer()
            buffer = part

    flush_buffer()
    return chunks


def long_text_output_path(character: str, filename: str, source_text: str) -> Path:
    requested = str(filename or "").strip()
    if not requested:
        return output_name(character, source_text, "長文結合")

    stem = join_safe_stem(requested)
    if not stem:
        return output_name(character, source_text, "長文結合")

    game_name = speaker_game_name(character)
    output_dir = OUTPUT_ROOT
    if game_name and str(character or "").strip():
        output_dir = generated_character_dir(game_name, character)
    output_dir.mkdir(parents=True, exist_ok=True)

    candidate = output_dir / f"{stem}.wav"
    index = 2
    while candidate.exists():
        candidate = output_dir / f"{stem}_{index}.wav"
        index += 1
    return candidate

def long_text_temp_output_path(character: str, filename: str, source_text: str) -> Path:
    requested = str(filename or "").strip()
    if requested:
        stem = join_safe_stem(requested)
    else:
        summary = safe_name(
            str(source_text).strip().replace("。", "").replace("、", ""),
            "長文",
            24,
        )
        stem = safe_name(f"{character}_{summary}_長文", "長文", 100)

    output_dir = TEMP_GENERATION_ROOT / "_long" / safe_name(character, "キャラクター")
    output_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    candidate = output_dir / f"{safe_name(stem, '長文', 100)}_{stamp}.wav"
    index = 2
    while candidate.exists():
        candidate = output_dir / f"{safe_name(stem, '長文', 100)}_{stamp}_{index}.wav"
        index += 1
    return candidate



def generation_queue_snapshot() -> list[dict[str, Any]]:
    with _generation_queue_lock:
        return [dict(item) for item in _generation_jobs]


def generation_queue_render_token() -> str:
    jobs = generation_queue_snapshot()
    payload = [
        {
            "id": int(item.get("id", 0) or 0),
            "status": str(item.get("status", "")),
            "error": str(item.get("error", "")),
        }
        for item in jobs
    ]
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def generation_queue_summary() -> str:
    jobs = generation_queue_snapshot()
    counts = {
        name: sum(1 for item in jobs if item.get("status") == name)
        for name in ("順番待ち", "生成中", "完了", "失敗")
    }
    return (
        f"生成中 {counts['生成中']} / "
        f"待ち {counts['順番待ち']} / "
        f"完了 {counts['完了']} / "
        f"失敗 {counts['失敗']}"
    )


def enqueue_long_text_generation(
    character: str,
    text: str,
    caption: str,
    ref_seconds: int,
    max_chars: int,
    interval: float,
    output_filename: str,
    emotion_mix: dict[str, Any] | None,
    cfg_scale_caption: float,
    emoji_enabled: bool,
    emoji_strength: str,
    cfg_scale_speaker: float,
    speaker_kv_enabled: bool,
    speaker_kv_scale: float,
) -> tuple[str, str, str, str, Any, Any]:
    global _generation_job_counter, _long_generation_group_counter

    character_name = str(character or "").strip()
    request_text = str(text or "").strip()
    if not character_name:
        return (
            str(text or ""), generation_queue_render_token(), "",
            "エラー：キャラクターを選択してください。",
            gr.Timer(active=False), gr.Timer(active=False),
        )
    if not request_text:
        return (
            str(text or ""), generation_queue_render_token(), "",
            "エラー：長文を入力してください。",
            gr.Timer(active=False), gr.Timer(active=False),
        )

    chunks = split_long_text(request_text, int(max_chars))
    if not chunks:
        return (
            str(text or ""), generation_queue_render_token(), "",
            "エラー：分割できる文章がありません。",
            gr.Timer(active=False), gr.Timer(active=False),
        )

    seconds = int(ref_seconds)
    gap = max(0.0, round(float(interval) * 10.0) / 10.0)
    mix = dict(emotion_mix or {})
    caption_scale, speaker_scale, kv_scale = normalize_generation_controls(
        cfg_scale_caption,
        cfg_scale_speaker,
        float(speaker_kv_scale) if speaker_kv_enabled else None,
    )
    mix_keys = [key for key, value in mix.items() if float(value or 0) > 0]
    mix_suffix = "_".join(mix_keys[:3])
    with _generation_queue_lock:
        _long_generation_group_counter += 1
        group_id = (
            f"long-{datetime.now().strftime('%Y%m%d%H%M%S%f')}-"
            f"{_long_generation_group_counter}"
        )
        _long_generation_groups[group_id] = {
            "id": group_id,
            "status": "生成中",
            "character": character_name,
            "source_text": request_text,
            "interval": gap,
            "output_filename": str(output_filename or "").strip(),
            "caption": str(caption or "").strip(),
            "ref_seconds": seconds,
            "emotion_mix": mix,
            "cfg_scale_caption": caption_scale,
            "emoji_enabled": bool(emoji_enabled),
            "emoji_strength": str(emoji_strength or "通常"),
            "cfg_scale_speaker": speaker_scale,
            "speaker_kv_scale": kv_scale,
            "output": "",
            "saved": False,
            "error": "",
            "segment_total": len(chunks),
        }

        for segment_index, chunk in enumerate(chunks, start=1):
            _generation_job_counter += 1
            _generation_jobs.append({
                "id": _generation_job_counter,
                "order": len(_generation_jobs) + 1,
                "status": "順番待ち",
                "character": character_name,
                "text": chunk,
                "caption": str(caption or "").strip(),
                "ref_seconds": seconds,
                "emotion_key": "",
                "emotion_mix": mix,
                "cfg_scale_caption": caption_scale,
                "emoji_enabled": bool(emoji_enabled),
                "emoji_strength": str(emoji_strength or "通常"),
                "cfg_scale_speaker": speaker_scale,
                "speaker_kv_scale": kv_scale,
                "suffix": (
                    f"長文_{mix_suffix}_{segment_index:03d}"
                    if mix_suffix
                    else f"長文_{segment_index:03d}"
                ),
                "output": "",
                "filename": "",
                "error": "",
                "long_group_id": group_id,
                "long_segment_index": segment_index,
                "long_segment_total": len(chunks),
            })

    _ensure_generation_worker()
    return (
        str(text or ""),
        generation_queue_render_token(),
        group_id,
        f"長文を {len(chunks)} 区切りに分割して生成キューへ追加しました。完了後に自動結合します。",
        gr.Timer(active=True),
        gr.Timer(active=True),
    )


def _finalize_long_group_if_ready(group_id: str) -> None:
    if not group_id:
        return

    with _generation_queue_lock:
        group = _long_generation_groups.get(group_id)
        if not isinstance(group, dict):
            return

        related = [
            item
            for item in _generation_jobs
            if item.get("long_group_id") == group_id
        ]
        if not related:
            return

        failed = [item for item in related if item.get("status") == "失敗"]
        if failed:
            group["status"] = "失敗"
            group["error"] = str(
                failed[0].get("error", "長文生成に失敗しました。")
            )
            return

        if any(item.get("status") != "完了" for item in related):
            return
        if group.get("status") in {"結合中", "完了"}:
            return

        group["status"] = "結合中"
        ordered = sorted(
            related,
            key=lambda item: int(item.get("long_segment_index", 0) or 0),
        )
        snapshot = [dict(item) for item in ordered]
        group_snapshot = dict(group)

    try:
        records = [
            {
                "path": str(item.get("output", "")),
                "filename": str(item.get("filename", "")),
                "interval": "",
            }
            for item in snapshot
        ]
        combined, target_channels = build_join_audio(
            records,
            float(group_snapshot.get("interval", 0.6) or 0.0),
        )
        output = long_text_temp_output_path(
            str(group_snapshot.get("character", "")),
            str(group_snapshot.get("output_filename", "")),
            str(group_snapshot.get("source_text", "")),
        )
        write_join_wav(output, combined, target_channels)

        for item in snapshot:
            _delete_temp_generation_path(str(item.get("output", "")))

        with _generation_queue_lock:
            current_group = _long_generation_groups.get(group_id)
            if isinstance(current_group, dict):
                current_group["status"] = "完了"
                current_group["output"] = str(output)
                current_group["saved"] = False
                current_group["error"] = ""
    except Exception as exc:
        with _generation_queue_lock:
            current_group = _long_generation_groups.get(group_id)
            if isinstance(current_group, dict):
                current_group["status"] = "失敗"
                current_group["error"] = str(exc)


def refresh_long_generation_ui(group_id: str) -> tuple[Any, str, Any, Any, Any]:
    if not str(group_id or "").strip():
        return (
            gr.skip(),
            "長文生成はまだ開始していません。",
            gr.Timer(active=False),
            gr.Button(interactive=False),
            gr.Button(interactive=False),
        )

    with _generation_queue_lock:
        group = dict(_long_generation_groups.get(str(group_id), {}))
        related = [
            dict(item)
            for item in _generation_jobs
            if item.get("long_group_id") == str(group_id)
        ]

    if not group:
        return (
            gr.skip(),
            "長文生成情報が見つかりません。",
            gr.Timer(active=False),
            gr.Button(interactive=False),
            gr.Button(interactive=False),
        )

    completed = sum(1 for item in related if item.get("status") == "完了")
    total = int(group.get("segment_total", len(related)) or len(related))
    status = str(group.get("status", "生成中"))

    if status == "完了" and group.get("output"):
        saved = bool(group.get("saved", False))
        return (
            str(group["output"]),
            (
                f"保存済み：{total} 区切りを1本へ結合しました。"
                if saved
                else f"未保存：{total} 区切りを1本へ結合しました。試聴後に保存または破棄してください。"
            ),
            gr.Timer(active=False),
            gr.Button(interactive=not saved),
            gr.Button(interactive=not saved),
        )
    if status == "破棄済み":
        return (
            None,
            "未保存の長文音声を破棄しました。",
            gr.Timer(active=False),
            gr.Button(interactive=False),
            gr.Button(interactive=False),
        )
    if status == "失敗":
        return (
            None,
            f"エラー：{group.get('error', '長文生成に失敗しました。')}",
            gr.Timer(active=False),
            gr.Button(interactive=False),
            gr.Button(interactive=False),
        )
    if status == "結合中":
        return (
            gr.skip(),
            f"生成 {completed}/{total} 完了。現在、1本のWAVへ結合中です。",
            gr.Timer(active=True),
            gr.Button(interactive=False),
            gr.Button(interactive=False),
        )
    return (
        gr.skip(),
        f"長文生成中：{completed}/{total} 完了。",
        gr.Timer(active=True),
        gr.Button(interactive=False),
        gr.Button(interactive=False),
    )


def save_long_generation(
    group_id: str,
) -> tuple[Any, str, Any, Any, list[list[Any]], Any]:
    with _generation_queue_lock:
        group = _long_generation_groups.get(str(group_id or ""))
        if not isinstance(group, dict):
            return (
                None,
                "長文生成情報が見つかりません。",
                gr.Button(interactive=False),
                gr.Button(interactive=False),
                history_rows(),
                history_dropdown(),
            )
        snapshot = dict(group)

    if bool(snapshot.get("saved")):
        return (
            str(snapshot.get("output", "")) or None,
            "この長文音声は保存済みです。",
            gr.Button(interactive=False),
            gr.Button(interactive=False),
            history_rows(),
            history_dropdown(),
        )

    source = Path(str(snapshot.get("output", "")))
    if not source.is_file() or not _is_temp_generation_path(source):
        return (
            None,
            "未保存の長文音声が見つかりません。",
            gr.Button(interactive=False),
            gr.Button(interactive=False),
            history_rows(),
            history_dropdown(),
        )

    target = long_text_output_path(
        str(snapshot.get("character", "")),
        str(snapshot.get("output_filename", "")),
        str(snapshot.get("source_text", "")),
    )
    shutil.move(str(source), str(target))

    entry = {
        "id": datetime.now().strftime("%Y%m%d%H%M%S%f"),
        "datetime": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "character": str(snapshot.get("character", "")),
        "text": str(snapshot.get("source_text", "")),
        "caption": str(snapshot.get("caption", "")),
        "ref_seconds": int(snapshot.get("ref_seconds", 120) or 120),
        "emotion_mix": dict(snapshot.get("emotion_mix", {})),
        "cfg_scale_caption": float(snapshot.get("cfg_scale_caption", 4.0) or 4.0),
        "cfg_scale_speaker": float(snapshot.get("cfg_scale_speaker", 5.0) or 5.0),
        "speaker_kv_scale": snapshot.get("speaker_kv_scale"),
        "emoji_enabled": bool(snapshot.get("emoji_enabled", False)),
        "emoji_strength": str(snapshot.get("emoji_strength", "通常")),
        "seed": 0,
        "long_text": True,
        "output": str(target),
    }
    append_history(entry)

    with _generation_queue_lock:
        group = _long_generation_groups.get(str(group_id or ""))
        if isinstance(group, dict):
            group["saved"] = True
            group["output"] = str(target)

    return (
        str(target),
        f"保存済み：{target}",
        gr.Button(interactive=False),
        gr.Button(interactive=False),
        history_rows(),
        history_dropdown(),
