def _generation_worker() -> None:
    global _generation_worker_thread

    while True:
        with _generation_queue_lock:
            job = next(
                (
                    item
                    for item in _generation_jobs
                    if item.get("status") == "順番待ち"
                ),
                None,
            )
            if job is None:
                _generation_worker_thread = None
                return

            job["status"] = "生成中"
            job["error"] = ""
            current = dict(job)

        try:
            with _generation_lock:
                runtime = get_runtime()
                seed = random.SystemRandom().randrange(1, 2_147_483_647)
                output, result, metadata = synthesize_one(
                    runtime,
                    str(current.get("character", "")),
                    str(current.get("text", "")),
                    str(current.get("caption", "")),
                    int(current.get("ref_seconds", 120)),
                    seed,
                    str(current.get("suffix", "キュー")),
                    str(current.get("emotion_key", "")),
                    current.get("emotion_mix", {}),
                    float(current.get("cfg_scale_caption", 4.0) or 4.0),
                    bool(current.get("emoji_enabled", False)),
                    str(current.get("emoji_strength", "通常")),
                    float(current.get("cfg_scale_speaker", 5.0) or 5.0),
                    current.get("speaker_kv_scale"),
                )

            result_id = None
            if not str(current.get("long_group_id", "")).strip():
                result_id = _register_generation_result(
                    str(output),
                    metadata,
                    str(current.get("suffix", "")),
                )

            with _generation_queue_lock:
                target = next(
                    (
                        item
                        for item in _generation_jobs
                        if item.get("id") == current.get("id")
                    ),
                    None,
                )
                if target is not None:
                    target["status"] = "完了"
                    target["output"] = str(output)
                    target["filename"] = Path(str(output)).name
                    target["seed"] = int(result.used_seed)
                    target["metadata"] = dict(metadata)
                    if result_id is not None:
                        target["result_id"] = int(result_id)
        except Exception as exc:
            with _generation_queue_lock:
                target = next(
                    (
                        item
                        for item in _generation_jobs
                        if item.get("id") == current.get("id")
                    ),
                    None,
                )
                if target is not None:
                    target["status"] = "失敗"
                    target["error"] = str(exc)

        group_id = str(current.get("long_group_id", ""))
        if group_id:
            _finalize_long_group_if_ready(group_id)


def _ensure_generation_worker() -> None:
    global _generation_worker_thread

    with _generation_queue_lock:
        if (
            _generation_worker_thread is not None
            and _generation_worker_thread.is_alive()
        ):
            return

        _generation_worker_thread = threading.Thread(
            target=_generation_worker,
            name="irodori-generation-queue",
            daemon=True,
        )
        _generation_worker_thread.start()


def enqueue_generation_requests(
    character: str,
    text: str,
    caption: str,
    ref_seconds: int,
    count: int,
    emotion_mix: dict[str, Any] | None,
    cfg_scale_caption: float,
    emoji_enabled: bool,
    emoji_strength: str,
    cfg_scale_speaker: float,
    speaker_kv_enabled: bool,
    speaker_kv_scale: float,
) -> tuple[str, str, str, Any]:
    global _generation_job_counter

    character_name = str(character or "").strip()
    request_text = str(text or "").strip()
    if not character_name:
        return (
            str(text or ""),
            generation_queue_render_token(),
            "エラー：キャラクターを選択してください。",
            gr.Timer(active=False),
        )
    if not request_text:
        return (
            str(text or ""),
            generation_queue_render_token(),
            "エラー：文章を入力してください。",
            gr.Timer(active=False),
        )

    seconds = int(ref_seconds)
    number = max(1, min(4, int(count)))
    mix = dict(emotion_mix or {})
    caption_scale, speaker_scale, kv_scale = normalize_generation_controls(
        cfg_scale_caption,
        cfg_scale_speaker,
        float(speaker_kv_scale) if speaker_kv_enabled else None,
    )
    mix_keys = [key for key, value in mix.items() if float(value or 0) > 0]
    mix_suffix = "_".join(mix_keys[:3])
    with _generation_queue_lock:
        for candidate_index in range(1, number + 1):
            _generation_job_counter += 1
            _generation_jobs.append({
                "id": _generation_job_counter,
                "order": len(_generation_jobs) + 1,
                "status": "順番待ち",
                "character": character_name,
                "text": request_text,
                "caption": str(caption or "").strip(),
                "ref_seconds": seconds,
                "emotion_key": "",
                "emotion_mix": mix,
                "cfg_scale_caption": caption_scale,
                "emoji_enabled": bool(emoji_enabled),
                "emoji_strength": str(emoji_strength or "通常"),
                "cfg_scale_speaker": speaker_scale,
                "speaker_kv_scale": kv_scale,
                "suffix": (
                    f"感情{mix_suffix}_候補{candidate_index}"
                    if mix_suffix
                    else f"参照{seconds}秒_候補{candidate_index}"
                ),
                "output": "",
                "filename": "",
                "error": "",
            })

    _ensure_generation_worker()
    return (
        str(text or ""),
        generation_queue_render_token(),
        f"{number}件を生成キューへ追加しました。入力欄はそのまま残しています。",
        gr.Timer(active=True),
    )


