def analyze_audio_tail(path: str | Path) -> dict[str, Any]:
    audio, sample_rate = sf.read(
        str(path),
        dtype="float32",
        always_2d=True,
    )
    if audio.size == 0 or int(sample_rate) <= 0:
        raise ValueError("音声データが空です。")

    mono = np.max(np.abs(audio), axis=1)
    duration = len(mono) / float(sample_rate)
    frame_size = max(1, int(round(sample_rate * 0.02)))
    frame_count = int(np.ceil(len(mono) / frame_size))
    rms = np.zeros(frame_count, dtype=np.float32)
    for index in range(frame_count):
        chunk = mono[index * frame_size:(index + 1) * frame_size]
        if len(chunk):
            rms[index] = float(np.sqrt(np.mean(np.square(chunk), dtype=np.float64)))

    peak_rms = float(rms.max()) if len(rms) else 0.0
    threshold = max(0.0025, peak_rms * 0.04)
    active = rms >= threshold
    active_indexes = np.flatnonzero(active)

    if len(active_indexes):
        last_active_end = min(
            duration,
            (int(active_indexes[-1]) + 1) * frame_size / float(sample_rate),
        )
    else:
        last_active_end = 0.0

    trailing_silence = max(0.0, duration - last_active_end)
    late_resume = False
    late_resume_gap = 0.0
    late_resume_start = 0.0
    speech_end_candidate = last_active_end
    if len(active_indexes) >= 2:
        gaps = np.diff(active_indexes)
        minimum_gap_frames = max(1, int(round(0.30 / 0.02)))
        for gap_index in range(len(gaps) - 1, -1, -1):
            if int(gaps[gap_index]) < minimum_gap_frames:
                continue
            resumed_index = int(active_indexes[gap_index + 1])
            resumed_time = resumed_index * frame_size / float(sample_rate)
            if duration - resumed_time <= 3.0:
                late_resume = True
                late_resume_gap = (
                    int(gaps[gap_index]) - 1
                ) * frame_size / float(sample_rate)
                late_resume_start = resumed_time
                speech_end_candidate = min(
                    duration,
                    (int(active_indexes[gap_index]) + 1)
                    * frame_size / float(sample_rate),
                )
                break

    after_speech_to_end = max(0.0, duration - speech_end_candidate)
    tail_samples = max(1, int(round(sample_rate * 0.50)))
    tail = mono[-tail_samples:]
    tail_rms = float(np.sqrt(np.mean(np.square(tail), dtype=np.float64))) if len(tail) else 0.0

    return {
        "duration": round(duration, 3),
        "last_active_end": round(last_active_end, 3),
        "speech_end_candidate": round(speech_end_candidate, 3),
        "after_speech_to_end": round(after_speech_to_end, 3),
        "trailing_silence": round(trailing_silence, 3),
        "tail_rms": round(tail_rms, 6),
        "late_resume": bool(late_resume),
        "late_resume_gap": round(late_resume_gap, 3),
        "late_resume_start": round(late_resume_start, 3),
        "threshold": round(threshold, 6),
    }


def compare_emoji_tail(
    character: str,
    text: str,
    caption: str,
    ref_seconds: int,
    emotion_mix: dict[str, Any] | None,
    cfg_scale_caption: float,
    emoji_strength: str,
    cfg_scale_speaker: float,
    speaker_kv_enabled: bool,
    speaker_kv_scale: float,
) -> tuple[Any, Any, Any, Any, str]:
    paths: list[str | None] = []
    try:
        mix = dict(emotion_mix or {})
        suffix = emotion_emoji_suffix(mix, "", emoji_strength)
        if not suffix:
            raise ValueError("比較する感情を1つ以上選択してください。")
        if not str(character or "").strip():
            raise ValueError("キャラクターを選択してください。")
        if not str(text or "").strip():
            raise ValueError("台詞を入力してください。")

        _current_caption_scale, _speaker_scale, kv_scale = normalize_generation_controls(
            cfg_scale_caption,
            cfg_scale_speaker,
            float(speaker_kv_scale) if speaker_kv_enabled else None,
        )
        specs = [
            ("A", False, 4.0),
            ("B", True, 4.0),
            ("C", False, 6.0),
            ("D", True, 6.0),
        ]
        metrics: dict[str, dict[str, Any]] = {}
        metadata_by_label: dict[str, dict[str, Any]] = {}

        with _generation_lock:
            runtime = get_runtime()
            for label, emoji_enabled, caption_scale in specs:
                path, _result, metadata = synthesize_one(
                    runtime,
                    character,
                    text,
                    caption,
                    int(ref_seconds),
                    EMOJI_TAIL_COMPARE_SEED,
                    f"末尾比較_{label}",
                    "",
                    mix,
                    caption_scale,
                    emoji_enabled,
                    emoji_strength,
                    cfg_scale_speaker,
                    kv_scale,
                )
                paths.append(path)
                metadata_by_label[label] = dict(metadata)

        for (label, _emoji_enabled, _caption_scale), path in zip(specs, paths):
            if path is None:
                continue
            metadata = metadata_by_label[label]
            _register_generation_result(path, metadata, f"末尾比較_{label}")
            metrics[label] = analyze_audio_tail(path)

        def line(label: str, title: str) -> str:
            values = metrics[label]
            metadata = metadata_by_label[label]
            processed = str(metadata.get("processed_text", "")).replace("`", "｀")
            resume = "なし"
            if bool(values["late_resume"]):
                resume = (
                    f"あり（{values['late_resume_start']:.3f}秒で再開 / "
                    f"空白 {values['late_resume_gap']:.3f}秒）"
                )
            return (
                f"**{label}：{title}**  "
                f"音声全長 {values['duration']:.3f}秒 / "
                f"生成処理 {float(metadata.get('synthesis_seconds', 0.0) or 0.0):.3f}秒 / "
                f"発話終了候補→終了 {values['after_speech_to_end']:.3f}秒 / "
                f"末尾無音 {values['trailing_silence']:.3f}秒 / "
                f"末尾0.5秒RMS {values['tail_rms']:.6f} / "
                f"末尾再発音候補 {resume}  \n"
                f"processed_text: `{processed}`"
            )

        def objectively_worse(test_label: str, base_label: str) -> bool:
            test = metrics[test_label]
            base = metrics[base_label]
            return bool(
                (bool(test["late_resume"]) and not bool(base["late_resume"]))
                or (
                    float(test["after_speech_to_end"])
                    - float(base["after_speech_to_end"])
                    >= 0.35
                )
                or (float(test["duration"]) - float(base["duration"]) >= 0.35)
                or (
                    float(test["late_resume_gap"])
                    - float(base["late_resume_gap"])
                    >= 0.30
                )
            )

        emoji_at_4 = objectively_worse("B", "A")
        emoji_at_6 = objectively_worse("D", "C")
        cfg6_without_emoji = objectively_worse("C", "A")
        cfg6_with_emoji = objectively_worse("D", "B")
        combined_vs_baseline = objectively_worse("D", "A")

        if emoji_at_4 and emoji_at_6 and not cfg6_without_emoji:
            provisional = "自動指標では、絵文字ONの影響が主因候補です。"
        elif cfg6_without_emoji and cfg6_with_emoji and not emoji_at_4:
            provisional = "自動指標では、感情の強さ6の影響が主因候補です。"
        elif combined_vs_baseline and not emoji_at_4 and not cfg6_without_emoji:
            provisional = "自動指標では、絵文字ONと感情の強さ6の組み合わせで悪化する可能性があります。"
        elif emoji_at_4 and cfg6_without_emoji:
            provisional = "自動指標では、絵文字ONと感情の強さ6の両方が独立に悪化要因となる可能性があります。"
        else:
            provisional = "自動指標だけでは、絵文字・感情の強さ6のどちらが主因か切り分けできません。"

        ba_duration = float(metrics["B"]["duration"]) - float(metrics["A"]["duration"])
        dc_duration = float(metrics["D"]["duration"]) - float(metrics["C"]["duration"])
        ca_duration = float(metrics["C"]["duration"]) - float(metrics["A"]["duration"])

        report = (
            f"同一キャラクター・台詞・seed {EMOJI_TAIL_COMPARE_SEED}・参照音声・感情配合・"
            f"声質設定で、絵文字と感情の強さだけを変えた4条件です。使用絵文字：{suffix}  \n\n"
            + line("A", "絵文字OFF / 感情の強さ4")
            + "  \n\n"
            + line("B", "絵文字ON / 感情の強さ4")
            + "  \n\n"
            + line("C", "絵文字OFF / 感情の強さ6")
            + "  \n\n"
            + line("D", "絵文字ON / 感情の強さ6")
            + "  \n\n"
            + f"音声全長差：B-A {ba_duration:+.3f}秒 / D-C {dc_duration:+.3f}秒 / C-A {ca_duration:+.3f}秒。  \n"
            + provisional
            + " 奇声・息・うなりの意味判定は実機試聴が必要です。"
            + " `trim_tail=True` は4条件すべて同じで、異常が無いことの根拠にはしません。"
        )
        return paths[0], paths[1], paths[2], paths[3], report
    except Exception as exc:
        while len(paths) < 4:
            paths.append(None)
        return paths[0], paths[1], paths[2], paths[3], f"エラー：{exc}"

def compare_emotion_controls(
    character: str,
    text: str,
    emotion_key: str,
) -> tuple[Any, ...]:
    paths: list[str | None] = []
    key = str(emotion_key or "").strip()
    if key not in EMOTION_KEYS:
        key = "cheerful"

    specs = [
        ("現行方式", 3.0, False),
        ("絵文字ON", 3.0, True),
        ("caption4", 4.0, False),
