            paths.append(None)
        return (*paths[:3], f"エラー：{exc}")


def compare_references(
    character: str,
    text: str,
    caption: str,
) -> tuple[Any, ...]:
    paths: list[str | None] = []
    messages: list[str] = []

    try:
        if not str(character or "").strip():
            raise ValueError("キャラクターを選択してください。")
        if not str(text or "").strip():
            raise ValueError("文章を入力してください。")

        with _generation_lock:
            runtime = get_runtime()
            for seconds in TARGET_SECONDS:
                output, result, _metadata = synthesize_one(
                    runtime,
                    character,
                    text,
                    caption,
                    seconds,
                    COMPARE_SEED,
                    f"比較{seconds}秒",
                    "",
                    None,
                    3.0,
                )
                paths.append(output)
                messages.append(f"{seconds}秒：{Path(output).name}")

