    except Exception as exc:
        while len(paths) < 4:
            paths.append(None)
        return (*paths[:4], f"エラー：{exc}")

files.update_and_start.ps1:
$ErrorActionPreference = 'Stop'

$jsonUrl = 'https://raw.githubusercontent.com/rensei11/00-tools/main/fandom-voice-tool-latest.json'
$url = 'http://127.0.0.1:7862/'
$toolDir = $PSScriptRoot

$statusPath = Join-Path $toolDir '_update_status.txt'
$updateLogPath = Join-Path $toolDir '_update_log.txt'
$payloadPath = Join-Path $toolDir '_update_payload.json'
$backupDir = Join-Path (Join-Path $toolDir '_backup') 'program_previous'
$createdNewFiles = New-Object 'System.Collections.Generic.List[string]'
$applyStarted = $false

$updateMutex = New-Object System.Threading.Mutex($false, 'FandomVoiceToolUpdate')
$hasUpdateMutex = $false
try {
    $hasUpdateMutex = $updateMutex.WaitOne(0)
} catch [System.Threading.AbandonedMutexException] {
    $hasUpdateMutex = $true
}
if (-not $hasUpdateMutex) {
    exit 0
}

function Set-UpdateStatus {
    param(
        [string]$Code,
        [string]$Reason = ''
    )

    $stamp = Get-Date -Format 'yyyy-MM-ddTHH:mm:ss'
    $value = "$Code|$stamp"
    if ($Reason) {
        $value += "|$Reason"
    }
    Set-Content -LiteralPath $statusPath -Value $value -Encoding Ascii
}

function Write-UpdateLog {
    param([string]$Text)

    try {
        Add-Content -LiteralPath $updateLogPath -Value $Text -Encoding UTF8
    } catch {
    }
}

function Get-SafeRelativeName {
    param([string]$Name)

    $value = [string]$Name
    if ([string]::IsNullOrWhiteSpace($value)) {
        throw 'Empty update path.'
    }

    $value = $value.Replace('/', '\').TrimStart([char]92)
    if ([System.IO.Path]::IsPathRooted($value)) {
        throw "Unsafe update path: $Name"
    }

    $segments = @($value -split '\\')
    if ($segments -contains '..') {
        throw "Unsafe update path: $Name"
    }

    $forbiddenDirs = @(
        '.git',
        '.github',
        '_backup',
        '_temp_generation',
        '_update_zip',
        '音声',
        '参照音声'
    )
    foreach ($segment in $segments) {
        if ($forbiddenDirs -contains $segment) {
            throw "Protected path is not allowed: $Name"
        }
    }

    $forbiddenFiles = @(
        'speakers.json',
        'games.json',
        'pronunciation_dictionary.json',
        'generation_history.jsonl'
    )
    if ($forbiddenFiles -contains $segments[-1]) {
        throw "Protected file is not allowed: $Name"
    }

    $extension = [System.IO.Path]::GetExtension($segments[-1]).ToLowerInvariant()
    if (@('.py', '.ps1', '.cmd', '.bat', '.json') -notcontains $extension) {
        throw "Unsupported update file type: $Name"
    }

    return $value
}

function Restore-ProgramBackup {
    if (Test-Path -LiteralPath $backupDir) {
        Get-ChildItem -LiteralPath $backupDir -File -Recurse | ForEach-Object {
            $relativeName = $_.FullName.Substring($backupDir.Length).TrimStart([char]92)
            $destination = Join-Path $toolDir $relativeName
            $destinationParent = Split-Path -Parent $destination
            if ($destinationParent) {
                New-Item -ItemType Directory -Force -Path $destinationParent | Out-Null
            }
            Copy-Item -LiteralPath $_.FullName -Destination $destination -Force
        }
    }

    foreach ($relativeName in $createdNewFiles) {
        Remove-Item -LiteralPath (Join-Path $toolDir $relativeName) -Force -ErrorAction SilentlyContinue
    }
}

function Stop-LocalApp {
    try {
        & wsl.exe -d Ubuntu -- bash -lc "pkill -f '/home/rensei/Irodori-TTS/.venv/bin/python [a]pp.py' || true" | Out-Null
    } catch {
    }
}

function Start-LocalApp {
    $launcher = Join-Path $toolDir 'start_local.ps1'
    if (-not (Test-Path -LiteralPath $launcher)) {
        throw 'start_local.ps1 was not found.'
    }

    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $launcher -NoBrowser
    if ($LASTEXITCODE -ne 0) {
        throw 'Local launcher failed.'
    }
}

function Wait-LocalApp {
    for ($attempt = 0; $attempt -lt 80; $attempt++) {
        Start-Sleep -Milliseconds 500
        try {
            $response = Invoke-WebRequest -Uri $url -TimeoutSec 2 -UseBasicParsing
            if ($response.StatusCode -eq 200) {
                return $true
            }
        } catch {
        }
    }
    return $false
}

try {
    Set-UpdateStatus 'STARTING'
    Remove-Item -LiteralPath $updateLogPath -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $payloadPath -Force -ErrorAction SilentlyContinue

    Set-UpdateStatus 'JSON_DOWNLOADING'
    $downloadWatch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        Invoke-WebRequest -Uri $jsonUrl -OutFile $payloadPath -UseBasicParsing -TimeoutSec 60
    } catch {
        Set-UpdateStatus 'FAILED' 'JSON_DOWNLOAD'
        throw 'Public update JSON download failed.'
    }
    $downloadWatch.Stop()
    Write-UpdateLog ('DOWNLOAD_SECONDS={0:F3}' -f $downloadWatch.Elapsed.TotalSeconds)

    try {
        $payloadText = [System.IO.File]::ReadAllText(
            $payloadPath,
            [System.Text.Encoding]::UTF8
        )
        $payload = $payloadText | ConvertFrom-Json
    } catch {
        Set-UpdateStatus 'FAILED' 'JSON_PARSE'
        throw 'Public update JSON could not be parsed.'
    }

    if (-not $payload.version -or -not $payload.files) {
        Set-UpdateStatus 'FAILED' 'JSON_FORMAT'
        throw 'Public update JSON is missing version or files.'
    }

    $entries = @($payload.files.PSObject.Properties)
    if ($entries.Count -eq 0) {
        Set-UpdateStatus 'FAILED' 'JSON_FORMAT'
        throw 'Public update JSON has no files.'
    }

    $safeEntries = New-Object 'System.Collections.Generic.List[object]'
    $seenPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entry in $entries) {
        $relativeName = Get-SafeRelativeName $entry.Name
        if (-not $seenPaths.Add($relativeName)) {
            throw "Duplicate update path: $relativeName"
        }

        $safeEntries.Add([pscustomobject]@{
            RelativeName = $relativeName
            Content = [string]$entry.Value
        }) | Out-Null
    }

    Stop-LocalApp
    Start-Sleep -Milliseconds 300

    Remove-Item -LiteralPath $backupDir -Recurse -Force -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
    $applyStarted = $true

    Set-UpdateStatus 'APPLYING'
    $applyWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)

    foreach ($entry in $safeEntries) {
        $relativeName = $entry.RelativeName
        $destination = Join-Path $toolDir $relativeName
        $destinationParent = Split-Path -Parent $destination
        if ($destinationParent) {
            New-Item -ItemType Directory -Force -Path $destinationParent | Out-Null
        }

        if (Test-Path -LiteralPath $destination) {
            $backupPath = Join-Path $backupDir $relativeName
            $backupParent = Split-Path -Parent $backupPath
            if ($backupParent) {
                New-Item -ItemType Directory -Force -Path $backupParent | Out-Null
            }
            Copy-Item -LiteralPath $destination -Destination $backupPath -Force
        } else {
            $createdNewFiles.Add($relativeName) | Out-Null
        }

        [System.IO.File]::WriteAllText(
            $destination,
            [string]$entry.Content,
            $utf8NoBom
        )
    }

    $applyWatch.Stop()
    Write-UpdateLog ('APPLY_SECONDS={0:F3}' -f $applyWatch.Elapsed.TotalSeconds)

    Set-UpdateStatus 'RESTARTING'
    $restartWatch = [System.Diagnostics.Stopwatch]::StartNew()
    Start-LocalApp
    if (-not (Wait-LocalApp)) {
        throw 'Updated app did not start.'
    }
    $restartWatch.Stop()
    Write-UpdateLog ('RESTART_SECONDS={0:F3}' -f $restartWatch.Elapsed.TotalSeconds)

    Remove-Item -LiteralPath $payloadPath -Force -ErrorAction SilentlyContinue
    Set-UpdateStatus 'SUCCESS'
    exit 0
} catch {
    $message = $_.Exception.Message
    Write-UpdateLog ('ERROR=' + $message)

    if ($applyStarted) {
        try {
            Restore-ProgramBackup
            Stop-LocalApp
            Start-Sleep -Milliseconds 300
            Start-LocalApp
            if (Wait-LocalApp) {
                Set-UpdateStatus 'FAILED' 'ROLLED_BACK'
                exit 1
            }
        } catch {
            Write-UpdateLog ('ROLLBACK_ERROR=' + $_.Exception.Message)
        }

        Set-UpdateStatus 'FAILED' 'ROLLBACK_START'
        exit 1
    }

    try {
        $currentStatus = ''
        if (Test-Path -LiteralPath $statusPath) {
            $currentStatus = (Get-Content -LiteralPath $statusPath -Raw -ErrorAction SilentlyContinue).Trim()
        }
        if (-not $currentStatus.StartsWith('FAILED|')) {
            Set-UpdateStatus 'FAILED' 'UNEXPECTED'
        }
    } catch {
    }
    exit 1
} finally {
    Remove-Item -LiteralPath $payloadPath -Force -ErrorAction SilentlyContinue
    if ($hasUpdateMutex) {
        $updateMutex.ReleaseMutex()
    }
    $updateMutex.Dispose()
}
